INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-2-01', 'awl-2', 'Học thuật Sublist 2 · Bộ 1', 'Academic Word List, sublist 2', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 1, 'achieve', 'đạt được; giành được', 'verb', '[{"en":"Few new businesses achieve success in their first year.","vi":"Rất ít doanh nghiệp mới đạt được thành công ngay trong năm đầu tiên."},{"en":"The company failed to achieve its sales targets this year.","vi":"Năm nay công ty đã không đạt được các chỉ tiêu doanh số."},{"en":"Students who set clear goals usually achieve better results.","vi":"Những sinh viên đặt ra mục tiêu rõ ràng thường đạt được kết quả tốt hơn."}]', '[{"phrase":"achieve success"},{"phrase":"achieve a goal"},{"phrase":"achieve results"},{"phrase":"achieve a target"}]', NULL, '/əˈtʃiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achieve__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 2, 'acquire', 'tiếp thu; có được; mua lại', 'verb', '[{"en":"Children acquire language skills very quickly in their early years.","vi":"Trẻ em tiếp thu các kỹ năng ngôn ngữ rất nhanh trong những năm đầu đời."},{"en":"Workers can acquire new skills through short training courses.","vi":"Người lao động có thể có được kỹ năng mới qua các khóa đào tạo ngắn hạn."},{"en":"Last year the firm acquired a smaller rival for two million dollars.","vi":"Năm ngoái, công ty đã mua lại một đối thủ nhỏ hơn với giá hai triệu đô la."}]', '[{"phrase":"acquire skills"},{"phrase":"acquire knowledge"},{"phrase":"acquire a company"}]', NULL, '/əˈkwaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquire__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 3, 'administrate', 'quản lý; điều hành', 'verb', '[{"en":"A small team administrates the scholarship program for the university.","vi":"Một nhóm nhỏ quản lý chương trình học bổng của trường đại học."},{"en":"She was hired to administrate the new research center.","vi":"Cô ấy được tuyển dụng để điều hành trung tâm nghiên cứu mới."},{"en":"Local councils administrate most public services in the region.","vi":"Chính quyền địa phương quản lý hầu hết các dịch vụ công trong khu vực."}]', '[{"phrase":"administrate a program"},{"phrase":"administrate funds"}]', 'Thường dùng administer; danh từ: administration', '/æˈdmɪnɪˌstreɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 4, 'affect', 'ảnh hưởng đến; tác động đến', 'verb', '[{"en":"Rising prices affect low-income families more than anyone else.","vi":"Giá cả tăng ảnh hưởng đến các gia đình thu nhập thấp nhiều hơn ai hết."},{"en":"The storm seriously affected transport across the northern region.","vi":"Cơn bão đã ảnh hưởng nghiêm trọng đến giao thông khắp khu vực phía bắc."},{"en":"Lack of sleep can affect your ability to concentrate.","vi":"Thiếu ngủ có thể ảnh hưởng đến khả năng tập trung của bạn."}]', '[{"phrase":"seriously affect"},{"phrase":"directly affect"},{"phrase":"adversely affect"}]', 'affect (v) ≠ effect (n)', '/əˈfekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affec/affect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 5, 'appropriate', 'phù hợp; thích hợp', 'adjective', '[{"en":"Please wear clothing appropriate for a formal business meeting.","vi":"Vui lòng mặc trang phục phù hợp với một cuộc họp công việc trang trọng."},{"en":"The committee will take appropriate action once the review is complete.","vi":"Ủy ban sẽ có biện pháp thích hợp sau khi việc xem xét hoàn tất."},{"en":"Is this textbook appropriate for first-year students?","vi":"Cuốn giáo trình này có phù hợp với sinh viên năm nhất không?"}]', '[{"phrase":"appropriate action"},{"phrase":"appropriate for"},{"phrase":"entirely appropriate"},{"phrase":"appropriate measures"}]', 'appropriate for + danh từ', '/əˈprəʊpriət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/appropriate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 6, 'aspect', 'khía cạnh; mặt', 'noun', '[{"en":"Cost is only one aspect of the problem we need to consider.","vi":"Chi phí chỉ là một khía cạnh của vấn đề mà chúng ta cần xem xét."},{"en":"The course covers all aspects of running a small business.","vi":"Khóa học bao quát mọi khía cạnh của việc điều hành một doanh nghiệp nhỏ."},{"en":"Researchers studied the social aspects of online learning.","vi":"Các nhà nghiên cứu đã tìm hiểu các khía cạnh xã hội của việc học trực tuyến."}]', '[{"phrase":"aspect of"},{"phrase":"all aspects"},{"phrase":"important aspect"},{"phrase":"social aspects"}]', NULL, '/ˈæspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/asp/aspec/aspect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 7, 'assist', 'hỗ trợ; giúp đỡ', 'verb', '[{"en":"Two graduate students assisted the professor with the experiment.","vi":"Hai học viên cao học đã hỗ trợ giáo sư thực hiện thí nghiệm."},{"en":"Our staff members are available to assist customers with their questions.","vi":"Nhân viên của chúng tôi luôn sẵn sàng giúp đỡ khách hàng giải đáp thắc mắc."},{"en":"The new software will assist doctors in making faster diagnoses.","vi":"Phần mềm mới sẽ hỗ trợ các bác sĩ chẩn đoán nhanh hơn."}]', '[{"phrase":"assist with"},{"phrase":"assist in"},{"phrase":"assist customers"}]', 'assist sb with sth / in doing sth', '/əˈsɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 8, 'category', 'loại; hạng mục; nhóm', 'noun', '[{"en":"The products are divided into three main categories.","vi":"Các sản phẩm được chia thành ba loại chính."},{"en":"She won an award in the best new writer category.","vi":"Cô ấy đã giành giải ở hạng mục nhà văn mới xuất sắc nhất."},{"en":"Most of the patients in the study fall into this category.","vi":"Phần lớn bệnh nhân trong nghiên cứu thuộc nhóm này."}]', '[{"phrase":"fall into a category"},{"phrase":"main category"},{"phrase":"broad category"}]', NULL, '/ˈkætəɡɔːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/categ/category__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 9, 'chapter', 'chương (sách); giai đoạn', 'noun', '[{"en":"Please read the first two chapters before next week''s seminar.","vi":"Vui lòng đọc hai chương đầu tiên trước buổi thảo luận tuần sau."},{"en":"Chapter three discusses the causes of the economic crisis.","vi":"Chương ba bàn về nguyên nhân của cuộc khủng hoảng kinh tế."},{"en":"Moving abroad opened a new chapter in her career.","vi":"Việc ra nước ngoài đã mở ra một giai đoạn mới trong sự nghiệp của cô ấy."}]', '[{"phrase":"the first chapter"},{"phrase":"the final chapter"},{"phrase":"a new chapter"}]', NULL, '/ˈtʃæptər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chapt/chapter__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 10, 'commission', 'ủy ban; tiền hoa hồng', 'noun', '[{"en":"The government set up a commission to investigate the accident.","vi":"Chính phủ đã thành lập một ủy ban để điều tra vụ tai nạn."},{"en":"Sales staff earn a commission on every car they sell.","vi":"Nhân viên bán hàng được hưởng tiền hoa hồng trên mỗi chiếc xe họ bán."},{"en":"The commission will publish its final report next spring.","vi":"Ủy ban sẽ công bố báo cáo cuối cùng vào mùa xuân năm sau."}]', '[{"phrase":"set up a commission"},{"phrase":"independent commission"},{"phrase":"earn commission"},{"phrase":"commission on"}]', NULL, '/kəˈmɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commission__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 11, 'community', 'cộng đồng', 'noun', '[{"en":"The new library will serve the whole local community.","vi":"Thư viện mới sẽ phục vụ toàn thể cộng đồng địa phương."},{"en":"Members of the scientific community welcomed the new findings.","vi":"Các thành viên trong cộng đồng khoa học đã hoan nghênh những phát hiện mới."},{"en":"Volunteers organized a community event to clean up the park.","vi":"Các tình nguyện viên đã tổ chức một sự kiện cộng đồng để dọn dẹp công viên."}]', '[{"phrase":"local community"},{"phrase":"scientific community"},{"phrase":"business community"},{"phrase":"community service"}]', NULL, '/kəˈmjuːnəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/community__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 12, 'complex', 'phức tạp', 'adjective', '[{"en":"Climate change is a complex problem with no simple solution.","vi":"Biến đổi khí hậu là một vấn đề phức tạp, không có giải pháp đơn giản."},{"en":"The brain is the most complex organ in the human body.","vi":"Não là cơ quan phức tạp nhất trong cơ thể con người."},{"en":"The application rules were too complex for most people to follow.","vi":"Các quy định nộp đơn quá phức tạp khiến hầu hết mọi người khó làm theo."}]', '[{"phrase":"complex problem"},{"phrase":"complex issue"},{"phrase":"highly complex"},{"phrase":"complex system"}]', NULL, '/kəmˈpleks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complex__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 13, 'compute', 'tính toán', 'verb', '[{"en":"The program computes the average score for each class.","vi":"Chương trình tính điểm trung bình cho từng lớp."},{"en":"Researchers computed the total cost of the project.","vi":"Các nhà nghiên cứu đã tính toán tổng chi phí của dự án."},{"en":"It is difficult to compute the exact risk of an earthquake.","vi":"Rất khó để tính toán chính xác nguy cơ xảy ra động đất."}]', '[{"phrase":"compute the average"},{"phrase":"compute the total"},{"phrase":"compute the cost"}]', NULL, '/kəmˈpjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/compute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 14, 'conclude', 'kết luận; kết thúc', 'verb', '[{"en":"The study concluded that exercise improves memory in older adults.","vi":"Nghiên cứu kết luận rằng tập thể dục giúp cải thiện trí nhớ ở người lớn tuổi."},{"en":"From the evidence, we can conclude that the plan has failed.","vi":"Từ các bằng chứng, chúng ta có thể kết luận rằng kế hoạch đã thất bại."},{"en":"The conference concluded with a short speech from the director.","vi":"Hội nghị kết thúc bằng một bài phát biểu ngắn của giám đốc."}]', '[{"phrase":"conclude that"},{"phrase":"conclude with"},{"phrase":"the report concludes"}]', 'conclude that + mệnh đề', '/kənˈkluːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclude__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 15, 'conduct', 'tiến hành; thực hiện', 'verb', '[{"en":"The team conducted a survey of five hundred local businesses.","vi":"Nhóm đã tiến hành khảo sát năm trăm doanh nghiệp địa phương."},{"en":"Scientists are conducting experiments to test the new vaccine.","vi":"Các nhà khoa học đang tiến hành thí nghiệm để kiểm tra vắc-xin mới."},{"en":"All interviews were conducted in English by trained staff.","vi":"Tất cả các cuộc phỏng vấn đều được nhân viên đã qua đào tạo thực hiện bằng tiếng Anh."}]', '[{"phrase":"conduct research"},{"phrase":"conduct a survey"},{"phrase":"conduct an experiment"},{"phrase":"conduct an interview"}]', NULL, '/kənˈdʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xconduct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 16, 'consequent', 'là hệ quả; kéo theo', 'adjective', '[{"en":"The factory closed, with a consequent loss of two hundred jobs.","vi":"Nhà máy đóng cửa, kéo theo việc mất đi hai trăm việc làm."},{"en":"Heavy rain and the consequent flooding damaged many homes.","vi":"Mưa lớn cùng trận lũ lụt do nó gây ra đã làm hư hại nhiều ngôi nhà."},{"en":"Rising fuel prices and the consequent increase in costs worried farmers.","vi":"Giá nhiên liệu tăng và chi phí tăng theo đã khiến nông dân lo lắng."}]', '[{"phrase":"consequent loss"},{"phrase":"consequent increase"},{"phrase":"consequent upon"}]', 'Trạng từ: consequently (do đó)', '/ˈkɑːnsɪkwent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequent__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 17, 'construct', 'xây dựng; dựng nên', 'verb', '[{"en":"The bridge was constructed in less than two years.","vi":"Cây cầu được xây dựng trong vòng chưa đầy hai năm."},{"en":"The city plans to construct a new hospital near the station.","vi":"Thành phố dự định xây dựng một bệnh viện mới gần nhà ga."},{"en":"Students must construct a clear argument supported by evidence.","vi":"Sinh viên phải xây dựng một lập luận rõ ràng có bằng chứng hỗ trợ."}]', '[{"phrase":"construct an argument"},{"phrase":"construct a model"},{"phrase":"newly constructed"}]', NULL, '/kənˈstrʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 18, 'consume', 'tiêu thụ; tiêu tốn', 'verb', '[{"en":"Older cars consume much more fuel than modern ones.","vi":"Xe ô tô đời cũ tiêu thụ nhiều nhiên liệu hơn hẳn so với xe hiện đại."},{"en":"People in cities consume more energy than those in rural areas.","vi":"Người dân thành thị tiêu thụ nhiều năng lượng hơn người dân nông thôn."},{"en":"Writing the final report consumed most of our time.","vi":"Việc viết báo cáo cuối cùng đã tiêu tốn phần lớn thời gian của chúng tôi."}]', '[{"phrase":"consume energy"},{"phrase":"consume fuel"},{"phrase":"consume resources"}]', NULL, '/kənˈsuːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsume__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 19, 'credit', 'tín dụng; tín chỉ; sự ghi nhận công lao', 'noun', '[{"en":"Many small businesses find it hard to get credit from banks.","vi":"Nhiều doanh nghiệp nhỏ gặp khó khăn khi vay tín dụng từ ngân hàng."},{"en":"Students must earn thirty credits to finish the program.","vi":"Sinh viên phải tích lũy ba mươi tín chỉ để hoàn thành chương trình."},{"en":"She deserves credit for the success of the project.","vi":"Cô ấy xứng đáng được ghi nhận công lao trong thành công của dự án."}]', '[{"phrase":"deserve credit"},{"phrase":"take credit for"},{"phrase":"earn credits"},{"phrase":"credit card"}]', NULL, '/ˈkredɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/credi/credit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 20, 'culture', 'văn hóa', 'noun', '[{"en":"Learning a language helps you understand a different culture.","vi":"Học một ngôn ngữ giúp bạn hiểu một nền văn hóa khác."},{"en":"The company has a strong culture of teamwork.","vi":"Công ty có văn hóa làm việc nhóm rất mạnh."},{"en":"Young people are strongly shaped by popular culture and social media.","vi":"Giới trẻ chịu ảnh hưởng mạnh mẽ của văn hóa đại chúng và mạng xã hội."}]', '[{"phrase":"popular culture"},{"phrase":"corporate culture"},{"phrase":"local culture"},{"phrase":"culture of"}]', NULL, '/ˈkʌltʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/culture__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 21, 'design', 'thiết kế', 'verb', '[{"en":"The building was designed to use as little energy as possible.","vi":"Tòa nhà được thiết kế để sử dụng ít năng lượng nhất có thể."},{"en":"Engineers are designing a cheaper battery for electric cars.","vi":"Các kỹ sư đang thiết kế một loại pin rẻ hơn cho xe điện."},{"en":"We designed the survey to be completed in ten minutes.","vi":"Chúng tôi thiết kế bản khảo sát để có thể hoàn thành trong mười phút."}]', '[{"phrase":"be designed to"},{"phrase":"specially designed"},{"phrase":"well designed"},{"phrase":"design a system"}]', NULL, '/dɪˈzaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/design__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 22, 'distinct', 'riêng biệt; khác biệt; rõ rệt', 'adjective', '[{"en":"The study identified three distinct groups of customers.","vi":"Nghiên cứu đã xác định ba nhóm khách hàng riêng biệt."},{"en":"Weather is distinct from climate, although people often confuse them.","vi":"Thời tiết khác biệt với khí hậu, dù mọi người thường nhầm lẫn hai khái niệm này."},{"en":"Speaking two languages gives job seekers a distinct advantage.","vi":"Việc nói được hai thứ tiếng mang lại cho người tìm việc một lợi thế rõ rệt."}]', '[{"phrase":"distinct from"},{"phrase":"clearly distinct"},{"phrase":"distinct advantage"}]', 'distinct from: khác với', '/dɪˈstɪŋkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 23, 'element', 'yếu tố; thành phần; nguyên tố', 'noun', '[{"en":"Trust is a key element of any successful team.","vi":"Sự tin tưởng là yếu tố then chốt của bất kỳ đội nhóm thành công nào."},{"en":"The plan contains several elements that need further discussion.","vi":"Kế hoạch có một số thành phần cần được thảo luận thêm."},{"en":"Oxygen is the most common element in Earth''s crust.","vi":"Ôxy là nguyên tố phổ biến nhất trong vỏ Trái Đất."}]', '[{"phrase":"key element"},{"phrase":"important element"},{"phrase":"element of"},{"phrase":"chemical element"}]', NULL, '/ˈelɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/eleme/element__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 24, 'equate', 'đánh đồng; tương đương với', 'verb', '[{"en":"Many people equate success with making a lot of money.","vi":"Nhiều người đánh đồng thành công với việc kiếm được nhiều tiền."},{"en":"We should not equate good grades with real understanding.","vi":"Chúng ta không nên đánh đồng điểm cao với sự hiểu biết thực sự."},{"en":"The pay rise equates to about fifty dollars a month.","vi":"Khoản tăng lương này tương đương khoảng năm mươi đô la mỗi tháng."}]', '[{"phrase":"equate with"},{"phrase":"equate to"}]', 'equate A with B: đánh đồng A với B', '/ɪˈkweɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equat/equate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 25, 'evaluate', 'đánh giá', 'verb', '[{"en":"Teachers evaluate students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"The study aimed to evaluate how well the new drug works.","vi":"Nghiên cứu nhằm đánh giá mức độ hiệu quả của loại thuốc mới."},{"en":"An outside expert was hired to evaluate the project.","vi":"Một chuyên gia bên ngoài đã được thuê để đánh giá dự án."}]', '[{"phrase":"evaluate the effectiveness"},{"phrase":"evaluate performance"},{"phrase":"evaluate progress"},{"phrase":"carefully evaluate"}]', NULL, '/ɪˈvæljueɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 26, 'feature', 'đặc điểm; tính năng', 'noun', '[{"en":"The latest version of the app includes several new features.","vi":"Phiên bản mới nhất của ứng dụng có thêm một số tính năng mới."},{"en":"A key feature of the course is its focus on practical skills.","vi":"Một đặc điểm chính của khóa học là chú trọng vào kỹ năng thực hành."},{"en":"High mountains are a common feature of the region''s landscape.","vi":"Núi cao là một đặc điểm phổ biến của cảnh quan vùng này."}]', '[{"phrase":"key feature"},{"phrase":"main feature"},{"phrase":"new features"},{"phrase":"common feature"}]', NULL, '/ˈfiːtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/featu/feature__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 27, 'final', 'cuối cùng; chung cuộc', 'adjective', '[{"en":"The final decision will be made by the board next month.","vi":"Quyết định cuối cùng sẽ được hội đồng quản trị đưa ra vào tháng sau."},{"en":"Students must submit their final reports by Friday.","vi":"Sinh viên phải nộp báo cáo cuối cùng trước thứ Sáu."},{"en":"The project is now in its final stage.","vi":"Dự án hiện đang ở giai đoạn cuối cùng."}]', '[{"phrase":"final decision"},{"phrase":"final stage"},{"phrase":"final result"},{"phrase":"final report"}]', NULL, '/ˈfaɪnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/final__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 28, 'focus', 'tập trung', 'verb', '[{"en":"This paper focuses on the effects of social media on teenagers.","vi":"Bài báo này tập trung vào tác động của mạng xã hội đối với thanh thiếu niên."},{"en":"Our company will focus on growth in Asian markets next year.","vi":"Năm tới, công ty chúng tôi sẽ tập trung vào tăng trưởng ở các thị trường châu Á."},{"en":"It is hard to focus when the office is so noisy.","vi":"Thật khó tập trung khi văn phòng quá ồn ào."}]', '[{"phrase":"focus on"},{"phrase":"focus attention on"},{"phrase":"mainly focus"}]', 'focus on + danh từ / V-ing', '/ˈfəʊkəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foc/focus/focus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 29, 'impact', 'tác động; ảnh hưởng', 'noun', '[{"en":"The new policy had a major impact on small businesses.","vi":"Chính sách mới đã có tác động lớn đến các doanh nghiệp nhỏ."},{"en":"Scientists are studying the impact of climate change on farming.","vi":"Các nhà khoa học đang nghiên cứu tác động của biến đổi khí hậu đối với nông nghiệp."},{"en":"Online shopping has had a negative impact on local stores.","vi":"Mua sắm trực tuyến đã gây ảnh hưởng tiêu cực đến các cửa hàng địa phương."}]', '[{"phrase":"have an impact on"},{"phrase":"major impact"},{"phrase":"negative impact"},{"phrase":"environmental impact"}]', 'impact on + danh từ', '/ˈɪmpækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impac/impact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-01', 30, 'injure', 'làm bị thương; gây chấn thương', 'verb', '[{"en":"Three workers were seriously injured in an accident at the factory.","vi":"Ba công nhân đã bị thương nặng trong một vụ tai nạn tại nhà máy."},{"en":"Players who train too hard are more likely to injure themselves.","vi":"Những cầu thủ tập luyện quá sức dễ tự gây chấn thương cho bản thân hơn."},{"en":"She injured her back while lifting heavy boxes at work.","vi":"Cô ấy bị chấn thương lưng khi nâng những thùng hàng nặng ở chỗ làm."}]', '[{"phrase":"seriously injured"},{"phrase":"badly injured"},{"phrase":"injure yourself"}]', 'Danh từ: injury (chấn thương)', '/ˈɪndʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injure__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-2-02', 'awl-2', 'Học thuật Sublist 2 · Bộ 2', 'Academic Word List, sublist 2', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 1, 'institute', 'viện; học viện', 'noun', '[{"en":"She works as a researcher at a national institute of health.","vi":"Cô ấy làm nhà nghiên cứu tại một viện y tế quốc gia."},{"en":"The institute publishes a report on air quality every year.","vi":"Viện này công bố báo cáo về chất lượng không khí hằng năm."},{"en":"He studied computer science at an institute of technology in the capital.","vi":"Anh ấy học khoa học máy tính tại một học viện công nghệ ở thủ đô."}]', '[{"phrase":"research institute"},{"phrase":"institute of technology"},{"phrase":"national institute"}]', NULL, '/ˈɪnstɪtuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institute__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 2, 'invest', 'đầu tư', 'verb', '[{"en":"The government plans to invest heavily in renewable energy.","vi":"Chính phủ dự định đầu tư mạnh vào năng lượng tái tạo."},{"en":"Many companies invested billions in new technology last year.","vi":"Năm ngoái, nhiều công ty đã đầu tư hàng tỷ vào công nghệ mới."},{"en":"Schools should invest more time in training their teachers.","vi":"Các trường học nên đầu tư nhiều thời gian hơn vào việc đào tạo giáo viên."}]', '[{"phrase":"invest in"},{"phrase":"invest heavily"},{"phrase":"invest money"},{"phrase":"invest time"}]', 'invest in + danh từ / V-ing', '/ɪnˈvest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/invest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 3, 'item', 'món; mặt hàng; mục', 'noun', '[{"en":"Customers can return any item within thirty days of purchase.","vi":"Khách hàng có thể trả lại bất kỳ món hàng nào trong vòng ba mươi ngày kể từ khi mua."},{"en":"The first item on the agenda is the new budget.","vi":"Mục đầu tiên trong chương trình họp là ngân sách mới."},{"en":"Food prices rose sharply, especially for basic items like rice and oil.","vi":"Giá thực phẩm tăng mạnh, đặc biệt là các mặt hàng thiết yếu như gạo và dầu ăn."}]', '[{"phrase":"item on the agenda"},{"phrase":"household items"},{"phrase":"individual items"}]', NULL, '/ˈaɪtəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ite/item_/item__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 4, 'journal', 'tạp chí chuyên ngành; nhật ký', 'noun', '[{"en":"The study was published in a leading medical journal.","vi":"Nghiên cứu này được đăng trên một tạp chí y khoa hàng đầu."},{"en":"Most researchers try to publish their work in peer-reviewed journals.","vi":"Hầu hết các nhà nghiên cứu cố gắng đăng công trình của mình trên các tạp chí có phản biện."},{"en":"Students keep a journal to record what they learn each week.","vi":"Sinh viên viết nhật ký để ghi lại những gì họ học được mỗi tuần."}]', '[{"phrase":"academic journal"},{"phrase":"medical journal"},{"phrase":"publish in a journal"},{"phrase":"keep a journal"}]', NULL, '/ˈdʒɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 5, 'maintain', 'duy trì; bảo dưỡng; khẳng định', 'verb', '[{"en":"The company has maintained high standards of quality for decades.","vi":"Công ty đã duy trì tiêu chuẩn chất lượng cao trong nhiều thập kỷ."},{"en":"The city spends millions each year to maintain its roads.","vi":"Thành phố chi hàng triệu mỗi năm để bảo dưỡng đường sá."},{"en":"He has always maintained that he did nothing wrong.","vi":"Anh ấy luôn khẳng định rằng mình không làm gì sai."}]', '[{"phrase":"maintain standards"},{"phrase":"maintain a balance"},{"phrase":"maintain contact"}]', NULL, '/meɪnˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintain__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 6, 'normal', 'bình thường', 'adjective', '[{"en":"Test results showed that her blood pressure was normal.","vi":"Kết quả xét nghiệm cho thấy huyết áp của cô ấy bình thường."},{"en":"Under normal conditions, the process takes about two weeks.","vi":"Trong điều kiện bình thường, quy trình này mất khoảng hai tuần."},{"en":"It is perfectly normal to feel nervous before a job interview.","vi":"Cảm thấy lo lắng trước buổi phỏng vấn xin việc là hoàn toàn bình thường."}]', '[{"phrase":"normal conditions"},{"phrase":"perfectly normal"},{"phrase":"return to normal"}]', NULL, '/ˈnɔːrml/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 7, 'obtain', 'có được; thu được; xin được', 'verb', '[{"en":"Researchers obtained the data from hospital records.","vi":"Các nhà nghiên cứu thu được dữ liệu từ hồ sơ bệnh viện."},{"en":"Foreign workers must obtain a work permit before starting their jobs.","vi":"Lao động nước ngoài phải xin được giấy phép lao động trước khi bắt đầu làm việc."},{"en":"Similar results were obtained in both experiments.","vi":"Cả hai thí nghiệm đều thu được kết quả tương tự."}]', '[{"phrase":"obtain data"},{"phrase":"obtain information"},{"phrase":"obtain permission"},{"phrase":"obtain a permit"}]', 'trang trọng hơn get', '/əbˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obt/obtai/obtain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 8, 'participate', 'tham gia', 'verb', '[{"en":"More than five hundred students participated in the survey.","vi":"Hơn năm trăm sinh viên đã tham gia cuộc khảo sát."},{"en":"Employees are encouraged to participate actively in team meetings.","vi":"Nhân viên được khuyến khích tích cực tham gia các cuộc họp nhóm."},{"en":"Would you like to participate in our research project?","vi":"Bạn có muốn tham gia dự án nghiên cứu của chúng tôi không?"}]', '[{"phrase":"participate in"},{"phrase":"participate actively"},{"phrase":"participate fully"}]', 'participate in + danh từ / V-ing', '/pɑːrˈtɪsɪpeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 9, 'perceive', 'nhận thấy; coi là; nhìn nhận', 'verb', '[{"en":"Many people perceive science as a difficult subject.","vi":"Nhiều người coi khoa học là một môn học khó."},{"en":"The company is widely perceived as a good place to work.","vi":"Công ty này được nhiều người nhìn nhận là một nơi làm việc tốt."},{"en":"Patients often perceive changes in their symptoms before doctors do.","vi":"Bệnh nhân thường nhận thấy những thay đổi trong triệu chứng của mình trước cả bác sĩ."}]', '[{"phrase":"perceive as"},{"phrase":"widely perceived"},{"phrase":"perceived risk"}]', 'perceive A as B: coi A là B', '/pərˈsiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perceive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 10, 'positive', 'tích cực; khả quan; dương tính', 'adjective', '[{"en":"The new policy has had a positive effect on staff morale.","vi":"Chính sách mới đã có tác động tích cực đến tinh thần nhân viên."},{"en":"Early results from the trial look very positive.","vi":"Kết quả ban đầu của cuộc thử nghiệm trông rất khả quan."},{"en":"Three members of the team tested positive for flu last week.","vi":"Tuần trước, ba thành viên trong nhóm có kết quả xét nghiệm dương tính với cúm."}]', '[{"phrase":"positive effect"},{"phrase":"positive attitude"},{"phrase":"positive feedback"},{"phrase":"test positive"}]', NULL, '/ˈpɑːzətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/positive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 11, 'potential', 'tiềm năng; tiềm tàng; có thể xảy ra', 'adjective', '[{"en":"The company is trying to attract potential customers through social media.","vi":"Công ty đang cố gắng thu hút khách hàng tiềm năng qua mạng xã hội."},{"en":"Scientists warned about the potential risks of the new drug.","vi":"Các nhà khoa học đã cảnh báo về những rủi ro tiềm tàng của loại thuốc mới."},{"en":"We need to identify potential problems before the project begins.","vi":"Chúng ta cần xác định những vấn đề có thể xảy ra trước khi dự án bắt đầu."}]', '[{"phrase":"potential customers"},{"phrase":"potential risks"},{"phrase":"potential benefits"}]', 'cũng là danh từ: tiềm năng (have potential)', '/pəˈtenʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potential__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 12, 'previous', 'trước; trước đây; trước đó', 'adjective', '[{"en":"Sales this year were higher than in the previous year.","vi":"Doanh số năm nay cao hơn so với năm trước."},{"en":"Unlike previous studies, this research focused on older adults.","vi":"Khác với các nghiên cứu trước đây, nghiên cứu này tập trung vào người cao tuổi."},{"en":"Applicants should have previous experience in customer service.","vi":"Ứng viên cần có kinh nghiệm trước đó trong lĩnh vực chăm sóc khách hàng."}]', '[{"phrase":"previous year"},{"phrase":"previous studies"},{"phrase":"previous experience"}]', NULL, '/ˈpriːviəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 13, 'primary', 'chính; chủ yếu; tiểu học', 'adjective', '[{"en":"The primary goal of the program is to reduce poverty.","vi":"Mục tiêu chính của chương trình là giảm nghèo."},{"en":"Poor diet is a primary cause of heart disease.","vi":"Chế độ ăn uống kém là một nguyên nhân chủ yếu gây bệnh tim."},{"en":"Most children in the country attend primary school until age eleven.","vi":"Hầu hết trẻ em ở nước này học tiểu học cho đến mười một tuổi."}]', '[{"phrase":"primary goal"},{"phrase":"primary cause"},{"phrase":"primary school"},{"phrase":"primary source"}]', NULL, '/ˈpraɪmeri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primary__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 14, 'purchase', 'mua; mua sắm', 'verb', '[{"en":"Tickets can be purchased online or at the station.","vi":"Vé có thể được mua trực tuyến hoặc tại nhà ga."},{"en":"The university purchased new equipment for its science laboratories.","vi":"Trường đại học đã mua thiết bị mới cho các phòng thí nghiệm khoa học."},{"en":"Many young people cannot afford to purchase a home.","vi":"Nhiều người trẻ không đủ khả năng mua nhà."}]', '[{"phrase":"purchase goods"},{"phrase":"purchase equipment"},{"phrase":"purchase online"}]', 'trang trọng hơn buy; cũng là danh từ: sự mua', '/ˈpɜːrtʃəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purch/purchase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 15, 'range', 'loạt; phạm vi; khoảng', 'noun', '[{"en":"The store offers a wide range of products at low prices.","vi":"Cửa hàng cung cấp rất nhiều loại sản phẩm với giá thấp."},{"en":"The report covers a range of topics, from health to education.","vi":"Báo cáo đề cập đến một loạt chủ đề, từ y tế đến giáo dục."},{"en":"Unfortunately, that hotel is outside our price range.","vi":"Tiếc là khách sạn đó nằm ngoài khoảng giá của chúng tôi."}]', '[{"phrase":"wide range"},{"phrase":"price range"},{"phrase":"age range"}]', 'a range of + danh từ số nhiều', '/reɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/range/range__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 16, 'region', 'vùng; khu vực', 'noun', '[{"en":"Coffee is grown mainly in the mountainous regions of the country.","vi":"Cà phê được trồng chủ yếu ở các vùng núi của đất nước."},{"en":"The storm caused serious damage across the whole region.","vi":"Cơn bão gây thiệt hại nghiêm trọng trên toàn khu vực."},{"en":"Which region has the highest rate of unemployment?","vi":"Khu vực nào có tỷ lệ thất nghiệp cao nhất?"}]', '[{"phrase":"mountainous region"},{"phrase":"coastal region"},{"phrase":"border region"}]', NULL, '/ˈriːdʒən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/region__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 17, 'regulate', 'điều tiết; quy định; điều chỉnh', 'verb', '[{"en":"The government regulates the prices of electricity and water.","vi":"Chính phủ điều tiết giá điện và nước."},{"en":"New laws will regulate how companies use personal data.","vi":"Các luật mới sẽ quy định cách các công ty sử dụng dữ liệu cá nhân."},{"en":"Sweating helps the body regulate its temperature.","vi":"Đổ mồ hôi giúp cơ thể điều chỉnh nhiệt độ."}]', '[{"phrase":"regulate prices"},{"phrase":"regulate temperature"},{"phrase":"strictly regulated"}]', NULL, '/ˈreɡjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 18, 'relevant', 'liên quan; phù hợp', 'adjective', '[{"en":"Please include only information that is relevant to the question.","vi":"Vui lòng chỉ đưa vào những thông tin liên quan đến câu hỏi."},{"en":"Candidates should have a degree in a relevant field.","vi":"Ứng viên cần có bằng cấp thuộc lĩnh vực liên quan."},{"en":"Are these old theories still relevant today?","vi":"Ngày nay, những lý thuyết cũ này có còn phù hợp không?"}]', '[{"phrase":"relevant to"},{"phrase":"relevant information"},{"phrase":"highly relevant"},{"phrase":"relevant experience"}]', 'relevant to + danh từ', '/ˈreləvənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relev/relevant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 19, 'reside', 'cư trú; sinh sống', 'verb', '[{"en":"Most of the survey participants reside in urban areas.","vi":"Phần lớn người tham gia khảo sát cư trú ở khu vực thành thị."},{"en":"Foreign students residing in the country must register with local authorities.","vi":"Sinh viên nước ngoài cư trú tại quốc gia này phải đăng ký với chính quyền địa phương."},{"en":"She has resided abroad for more than ten years.","vi":"Cô ấy đã sinh sống ở nước ngoài hơn mười năm."}]', '[{"phrase":"reside in"},{"phrase":"reside abroad"},{"phrase":"currently reside"}]', 'trang trọng hơn live; reside in + nơi chốn', '/rɪˈzaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resid/reside__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 20, 'resource', 'tài nguyên; nguồn lực', 'noun', '[{"en":"The country is rich in natural resources such as oil and gas.","vi":"Đất nước này giàu tài nguyên thiên nhiên như dầu mỏ và khí đốt."},{"en":"Small schools often lack the resources to support every student.","vi":"Các trường nhỏ thường thiếu nguồn lực để hỗ trợ mọi học sinh."},{"en":"We should use our limited resources more efficiently.","vi":"Chúng ta nên sử dụng nguồn lực hạn chế của mình hiệu quả hơn."}]', '[{"phrase":"natural resources"},{"phrase":"limited resources"},{"phrase":"human resources"},{"phrase":"allocate resources"}]', NULL, '/ˈriːsɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resou/resource__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 21, 'restrict', 'hạn chế; giới hạn', 'verb', '[{"en":"The new law restricts the sale of alcohol near schools.","vi":"Luật mới hạn chế việc bán rượu bia gần trường học."},{"en":"Access to the laboratory is restricted to authorized staff.","vi":"Quyền vào phòng thí nghiệm chỉ giới hạn cho nhân viên được cấp phép."},{"en":"Doctors advised him to restrict the amount of salt he eats.","vi":"Bác sĩ khuyên anh ấy hạn chế lượng muối ăn vào."}]', '[{"phrase":"restrict access"},{"phrase":"severely restrict"},{"phrase":"restricted to"}]', 'restrict something to: giới hạn trong phạm vi', '/rɪˈstrɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 22, 'secure', 'an toàn; bảo mật; ổn định', 'adjective', '[{"en":"Customers want to know that their personal data is secure.","vi":"Khách hàng muốn biết rằng dữ liệu cá nhân của họ được bảo mật."},{"en":"Many young graduates struggle to find secure employment.","vi":"Nhiều sinh viên mới tốt nghiệp chật vật để tìm được việc làm ổn định."},{"en":"Keep your passwords in a secure place.","vi":"Hãy cất giữ mật khẩu của bạn ở một nơi an toàn."}]', '[{"phrase":"secure place"},{"phrase":"secure employment"},{"phrase":"financially secure"}]', 'cũng là động từ: giành được (secure funding)', '/sɪˈkjʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/secure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 23, 'seek', 'tìm kiếm; tìm cách', 'verb', '[{"en":"Many graduates seek jobs abroad after finishing their studies.","vi":"Nhiều sinh viên tốt nghiệp tìm việc làm ở nước ngoài sau khi học xong."},{"en":"You should seek advice from a lawyer before signing the contract.","vi":"Bạn nên tìm lời khuyên từ luật sư trước khi ký hợp đồng."},{"en":"The study sought to explain why some students drop out.","vi":"Nghiên cứu này tìm cách lý giải vì sao một số sinh viên bỏ học."}]', '[{"phrase":"seek advice"},{"phrase":"seek help"},{"phrase":"seek to"},{"phrase":"seek employment"}]', 'seek – sought – sought', '/siːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seek_/seek__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 24, 'select', 'chọn; lựa chọn; tuyển chọn', 'verb', '[{"en":"Participants were selected at random from the local population.","vi":"Những người tham gia được chọn ngẫu nhiên từ dân cư địa phương."},{"en":"Only ten students were selected for the scholarship program.","vi":"Chỉ có mười sinh viên được tuyển chọn vào chương trình học bổng."},{"en":"Please select your preferred language from the list below.","vi":"Vui lòng chọn ngôn ngữ bạn muốn từ danh sách bên dưới."}]', '[{"phrase":"selected at random"},{"phrase":"carefully selected"},{"phrase":"select from"}]', NULL, '/sɪˈlekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/select__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 25, 'site', 'địa điểm; công trường; trang web', 'noun', '[{"en":"Workers must wear helmets at all times on the construction site.","vi":"Công nhân phải luôn đội mũ bảo hộ tại công trường xây dựng."},{"en":"The city has chosen a site for the new hospital.","vi":"Thành phố đã chọn được địa điểm cho bệnh viện mới."},{"en":"You can download the full report from our site.","vi":"Bạn có thể tải toàn bộ báo cáo từ trang web của chúng tôi."}]', '[{"phrase":"construction site"},{"phrase":"historic site"},{"phrase":"on site"}]', 'site ≠ sight (cảnh, tầm nhìn)', '/saɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/site_/site__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 26, 'strategy', 'chiến lược', 'noun', '[{"en":"The company needs a clear strategy to compete in foreign markets.","vi":"Công ty cần một chiến lược rõ ràng để cạnh tranh ở thị trường nước ngoài."},{"en":"Teachers used different strategies to help weaker students.","vi":"Giáo viên đã áp dụng nhiều chiến lược khác nhau để giúp đỡ học sinh yếu."},{"en":"The government has developed a national strategy for reducing waste.","vi":"Chính phủ đã xây dựng một chiến lược quốc gia nhằm giảm rác thải."}]', '[{"phrase":"develop a strategy"},{"phrase":"clear strategy"},{"phrase":"marketing strategy"},{"phrase":"long-term strategy"}]', NULL, '/ˈstrætədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strat/strategy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 27, 'survey', 'cuộc khảo sát; cuộc điều tra', 'noun', '[{"en":"A recent survey found that most employees prefer flexible hours.","vi":"Một cuộc khảo sát gần đây cho thấy phần lớn nhân viên thích giờ làm việc linh hoạt."},{"en":"We conducted a survey of two thousand households.","vi":"Chúng tôi đã tiến hành khảo sát hai nghìn hộ gia đình."},{"en":"Please take a few minutes to complete this short survey.","vi":"Vui lòng dành vài phút để hoàn thành bản khảo sát ngắn này."}]', '[{"phrase":"conduct a survey"},{"phrase":"recent survey"},{"phrase":"complete a survey"}]', NULL, '/ˈsɜːrveɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surve/survey__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 28, 'text', 'văn bản; bài đọc; tin nhắn', 'noun', '[{"en":"The full text of the agreement is available online.","vi":"Toàn bộ văn bản thỏa thuận được đăng tải trực tuyến."},{"en":"Students should read the text carefully before answering the questions.","vi":"Học sinh nên đọc kỹ bài đọc trước khi trả lời câu hỏi."},{"en":"I sent her a text to say I would be late.","vi":"Tôi đã nhắn tin cho cô ấy để báo rằng tôi sẽ đến muộn."}]', '[{"phrase":"full text"},{"phrase":"send a text"},{"phrase":"text message"}]', NULL, '/tekst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tex/text_/text__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 29, 'tradition', 'truyền thống', 'noun', '[{"en":"The festival is an important tradition in many Asian countries.","vi":"Lễ hội này là một truyền thống quan trọng ở nhiều nước châu Á."},{"en":"The university has a long tradition of academic excellence.","vi":"Trường đại học này có truyền thống lâu đời về thành tích học thuật xuất sắc."},{"en":"By tradition, the whole family gathers for a big meal at New Year.","vi":"Theo truyền thống, cả gia đình quây quần bên bữa cơm lớn vào dịp năm mới."}]', '[{"phrase":"long tradition"},{"phrase":"cultural tradition"},{"phrase":"by tradition"},{"phrase":"follow a tradition"}]', NULL, '/trəˈdɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/tradition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-2-02', 30, 'transfer', 'chuyển; chuyển giao; điều chuyển', 'verb', '[{"en":"Money can be transferred between accounts in a few seconds.","vi":"Tiền có thể được chuyển giữa các tài khoản chỉ trong vài giây."},{"en":"After two years, she was transferred to the company''s overseas office.","vi":"Sau hai năm, cô ấy được điều chuyển sang văn phòng ở nước ngoài của công ty."},{"en":"The project aims to transfer new farming technology to rural communities.","vi":"Dự án nhằm chuyển giao công nghệ canh tác mới cho các cộng đồng nông thôn."}]', '[{"phrase":"transfer money"},{"phrase":"transfer data"},{"phrase":"transfer technology"},{"phrase":"transfer to"}]', 'transfer – transferred (gấp đôi r)', '/trænsˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transfer__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-3-01', 'awl-3', 'Học thuật Sublist 3 · Bộ 1', 'Academic Word List, sublist 3', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 1, 'alternative', 'lựa chọn khác; phương án thay thế', 'noun', '[{"en":"Solar power offers a cleaner alternative to coal.","vi":"Năng lượng mặt trời mang lại một lựa chọn sạch hơn thay cho than đá."},{"en":"If the plan fails, we will need an alternative.","vi":"Nếu kế hoạch thất bại, chúng ta sẽ cần một phương án khác."},{"en":"The committee rejected both alternatives proposed by the consultants.","vi":"Ủy ban đã bác bỏ cả hai phương án do các chuyên gia tư vấn đề xuất."}]', '[{"phrase":"alternative to"},{"phrase":"viable alternative"},{"phrase":"offer an alternative"}]', NULL, '/ɔːlˈtɜːrnətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alternative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 2, 'circumstance', 'hoàn cảnh; tình huống', 'noun', '[{"en":"Under no circumstances should staff share their passwords.","vi":"Trong bất kỳ hoàn cảnh nào, nhân viên cũng không được chia sẻ mật khẩu."},{"en":"The meeting was postponed due to unforeseen circumstances.","vi":"Cuộc họp bị hoãn do những tình huống không lường trước được."},{"en":"Students in difficult financial circumstances can apply for extra support.","vi":"Sinh viên có hoàn cảnh tài chính khó khăn có thể nộp đơn xin hỗ trợ thêm."}]', '[{"phrase":"under no circumstances"},{"phrase":"unforeseen circumstances"},{"phrase":"financial circumstances"}]', 'thường dùng ở số nhiều: circumstances', '/ˈsɜːrkəmstæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circu/circumstance__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 3, 'comment', 'lời bình luận; nhận xét', 'noun', '[{"en":"Thank you for your helpful comments on my draft.","vi":"Cảm ơn những nhận xét hữu ích của bạn về bản nháp của tôi."},{"en":"The company made no comment on reports of job cuts.","vi":"Công ty không đưa ra bình luận nào về các tin tức cắt giảm việc làm."},{"en":"Several readers left comments below the online article.","vi":"Một số độc giả đã để lại bình luận bên dưới bài báo trực tuyến."}]', '[{"phrase":"make a comment"},{"phrase":"comment on"},{"phrase":"no comment"},{"phrase":"leave a comment"}]', NULL, '/ˈkɑːment/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/comment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 4, 'compensate', 'bồi thường; bù đắp', 'verb', '[{"en":"The airline agreed to compensate passengers for the delay.","vi":"Hãng hàng không đồng ý bồi thường cho hành khách vì chuyến bay bị trễ."},{"en":"Workers must be compensated for any injuries suffered on the job.","vi":"Người lao động phải được bồi thường cho mọi chấn thương gặp phải khi làm việc."},{"en":"Strong exports helped compensate for weak domestic demand.","vi":"Xuất khẩu mạnh đã giúp bù đắp cho nhu cầu trong nước yếu."}]', '[{"phrase":"compensate for"},{"phrase":"fully compensate"},{"phrase":"compensate victims"}]', 'compensate (sb) for sth', '/ˈkɑːmpenseɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compensate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 5, 'component', 'thành phần; bộ phận; linh kiện', 'noun', '[{"en":"Trust is a key component of any successful team.","vi":"Sự tin tưởng là một thành phần then chốt của bất kỳ nhóm thành công nào."},{"en":"The factory produces electronic components for mobile phones.","vi":"Nhà máy sản xuất linh kiện điện tử cho điện thoại di động."},{"en":"The course has three components: lectures, seminars and a final project.","vi":"Khóa học có ba thành phần: bài giảng, buổi thảo luận và một dự án cuối kỳ."}]', '[{"phrase":"key component"},{"phrase":"essential component"},{"phrase":"electronic components"}]', NULL, '/kəmˈpəʊnənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/component__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 6, 'consent', 'sự đồng ý; sự cho phép', 'noun', '[{"en":"Researchers must obtain written consent from all participants.","vi":"Các nhà nghiên cứu phải có được sự đồng ý bằng văn bản của tất cả người tham gia."},{"en":"Your data will not be shared without your consent.","vi":"Dữ liệu của bạn sẽ không được chia sẻ khi chưa có sự đồng ý của bạn."},{"en":"Parents must give consent before their children join the study.","vi":"Phụ huynh phải cho phép trước khi con em họ tham gia nghiên cứu."}]', '[{"phrase":"give consent"},{"phrase":"written consent"},{"phrase":"informed consent"},{"phrase":"without consent"}]', 'không đếm được', '/kənˈsent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 7, 'considerable', 'đáng kể; lớn', 'adjective', '[{"en":"The project has attracted considerable interest from investors.","vi":"Dự án đã thu hút sự quan tâm đáng kể từ các nhà đầu tư."},{"en":"Building the new bridge will take a considerable amount of time.","vi":"Việc xây cây cầu mới sẽ mất một khoảng thời gian đáng kể."},{"en":"There is considerable evidence that exercise improves memory.","vi":"Có khá nhiều bằng chứng cho thấy tập thể dục giúp cải thiện trí nhớ."}]', '[{"phrase":"considerable amount"},{"phrase":"considerable interest"},{"phrase":"considerable evidence"},{"phrase":"to a considerable extent"}]', 'considerable (đáng kể) ≠ considerate (chu đáo)', '/kənˈsɪdərəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsiderable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 8, 'constant', 'liên tục; không đổi', 'adjective', '[{"en":"The samples must be stored at a constant temperature.","vi":"Các mẫu phải được bảo quản ở nhiệt độ không đổi."},{"en":"Small businesses face constant pressure to cut costs.","vi":"Các doanh nghiệp nhỏ liên tục chịu áp lực phải cắt giảm chi phí."},{"en":"Prices remained constant throughout the first half of the year.","vi":"Giá cả giữ nguyên không đổi trong suốt nửa đầu năm."}]', '[{"phrase":"constant temperature"},{"phrase":"constant pressure"},{"phrase":"remain constant"},{"phrase":"constant change"}]', NULL, '/ˈkɑːnstənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 9, 'constrain', 'hạn chế; kìm hãm; ràng buộc', 'verb', '[{"en":"Growth has been constrained by a shortage of skilled workers.","vi":"Tăng trưởng đã bị kìm hãm do thiếu lao động có tay nghề."},{"en":"A small budget constrains what the research team can achieve.","vi":"Ngân sách ít ỏi hạn chế những gì nhóm nghiên cứu có thể đạt được."},{"en":"Many farmers feel constrained by strict environmental rules.","vi":"Nhiều nông dân cảm thấy bị ràng buộc bởi các quy định môi trường nghiêm ngặt."}]', '[{"phrase":"constrain growth"},{"phrase":"be constrained by"},{"phrase":"severely constrain"}]', NULL, '/kənˈstreɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstrain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 10, 'contribute', 'đóng góp; góp phần', 'verb', '[{"en":"Everyone is encouraged to contribute ideas during the meeting.","vi":"Mọi người được khuyến khích đóng góp ý kiến trong cuộc họp."},{"en":"Poor diet can contribute to heart disease.","vi":"Chế độ ăn uống kém có thể góp phần gây ra bệnh tim."},{"en":"Several local companies contributed funds to the new library.","vi":"Một số công ty địa phương đã đóng góp kinh phí cho thư viện mới."}]', '[{"phrase":"contribute to"},{"phrase":"contribute significantly"},{"phrase":"contribute funds"}]', 'contribute to sth', '/kənˈtrɪbjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 11, 'convene', 'triệu tập; nhóm họp', 'verb', '[{"en":"The director plans to convene a meeting with all department heads.","vi":"Giám đốc dự định triệu tập một cuộc họp với tất cả các trưởng phòng."},{"en":"The board will convene next week to discuss the budget.","vi":"Hội đồng quản trị sẽ nhóm họp vào tuần tới để thảo luận về ngân sách."},{"en":"An emergency meeting was convened after the data breach.","vi":"Một cuộc họp khẩn cấp đã được triệu tập sau vụ rò rỉ dữ liệu."}]', '[{"phrase":"convene a meeting"},{"phrase":"convene a conference"},{"phrase":"convene a panel"}]', NULL, '/kənˈviːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvene__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 12, 'coordinate', 'điều phối; phối hợp', 'verb', '[{"en":"She coordinates volunteer programs across three hospitals.","vi":"Cô ấy điều phối các chương trình tình nguyện tại ba bệnh viện."},{"en":"Emergency services must coordinate their efforts during a flood.","vi":"Các lực lượng cứu hộ phải phối hợp nỗ lực trong lúc xảy ra lũ lụt."},{"en":"Our team will coordinate with the sales department on the launch.","vi":"Nhóm chúng tôi sẽ phối hợp với phòng kinh doanh trong đợt ra mắt sản phẩm."}]', '[{"phrase":"coordinate efforts"},{"phrase":"coordinate with"},{"phrase":"coordinate activities"}]', NULL, '/kəʊˈɔːrdɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coord/coordinate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 13, 'core', 'cốt lõi; chủ chốt; chính', 'adjective', '[{"en":"Honesty is one of the company''s core values.","vi":"Trung thực là một trong những giá trị cốt lõi của công ty."},{"en":"Math and English are core subjects in most schools.","vi":"Toán và tiếng Anh là các môn học chính ở hầu hết các trường."},{"en":"The firm decided to focus on its core business.","vi":"Công ty quyết định tập trung vào mảng kinh doanh cốt lõi của mình."}]', '[{"phrase":"core values"},{"phrase":"core business"},{"phrase":"core subjects"}]', NULL, '/kɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/core_/core__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 14, 'corporate', 'thuộc doanh nghiệp; của công ty', 'adjective', '[{"en":"More companies now publish reports on corporate social responsibility.","vi":"Ngày càng nhiều công ty công bố báo cáo về trách nhiệm xã hội của doanh nghiệp."},{"en":"The firm has moved its corporate headquarters to the city center.","vi":"Công ty đã chuyển trụ sở chính về trung tâm thành phố."},{"en":"The government lowered the corporate tax rate to attract foreign investment.","vi":"Chính phủ đã hạ mức thuế doanh nghiệp để thu hút đầu tư nước ngoài."}]', '[{"phrase":"corporate headquarters"},{"phrase":"corporate culture"},{"phrase":"corporate social responsibility"},{"phrase":"corporate tax"}]', NULL, '/ˈkɔːrpərət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporate__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 15, 'correspond', 'tương ứng; phù hợp; trao đổi thư từ', 'verb', '[{"en":"The numbers on the map correspond to the photos below.","vi":"Các con số trên bản đồ tương ứng với các bức ảnh bên dưới."},{"en":"His account of events does not correspond with the evidence.","vi":"Lời kể của anh ta về sự việc không phù hợp với bằng chứng."},{"en":"The two researchers corresponded by email for several years.","vi":"Hai nhà nghiên cứu đã trao đổi thư từ qua email trong nhiều năm."}]', '[{"phrase":"correspond to"},{"phrase":"correspond with"},{"phrase":"correspond closely"}]', NULL, '/ˌkɔːrəˈspɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correspond__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 16, 'criteria', 'tiêu chí; tiêu chuẩn', 'noun', '[{"en":"Applicants must meet all the criteria listed below.","vi":"Ứng viên phải đáp ứng tất cả các tiêu chí được liệt kê dưới đây."},{"en":"What criteria did the judges use to choose the winner?","vi":"Ban giám khảo đã dùng những tiêu chí nào để chọn người chiến thắng?"},{"en":"The study used strict criteria for selecting participants.","vi":"Nghiên cứu đã áp dụng các tiêu chí nghiêm ngặt để chọn người tham gia."}]', '[{"phrase":"meet the criteria"},{"phrase":"strict criteria"},{"phrase":"selection criteria"}]', 'số nhiều của criterion', '/kraɪˈtɪriːə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 17, 'deduce', 'suy ra; suy luận', 'verb', '[{"en":"From the data, we can deduce that sales peak in December.","vi":"Từ dữ liệu, chúng ta có thể suy ra rằng doanh số đạt đỉnh vào tháng Mười Hai."},{"en":"Doctors deduced the cause of the illness from the patient''s symptoms.","vi":"Các bác sĩ đã suy ra nguyên nhân gây bệnh từ các triệu chứng của bệnh nhân."},{"en":"It is difficult to deduce much from such a small sample.","vi":"Thật khó suy ra được nhiều điều từ một mẫu nhỏ như vậy."}]', '[{"phrase":"deduce from"},{"phrase":"deduce that"}]', 'deduce sth from sth', '/dɪˈduːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/ded/deduc/deduce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 18, 'demonstrate', 'chứng minh; cho thấy; trình diễn', 'verb', '[{"en":"The study demonstrates a clear link between sleep and memory.","vi":"Nghiên cứu cho thấy mối liên hệ rõ ràng giữa giấc ngủ và trí nhớ."},{"en":"The trainer demonstrated how to use the new software.","vi":"Người hướng dẫn đã trình diễn cách sử dụng phần mềm mới."},{"en":"Candidates must demonstrate strong communication skills during the interview.","vi":"Ứng viên phải chứng minh được kỹ năng giao tiếp tốt trong buổi phỏng vấn."}]', '[{"phrase":"clearly demonstrate"},{"phrase":"demonstrate how"},{"phrase":"demonstrate skills"}]', NULL, '/ˈdemənstreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 19, 'document', 'tài liệu; văn bản; giấy tờ', 'noun', '[{"en":"Please bring all the necessary documents to the interview.","vi":"Vui lòng mang theo tất cả giấy tờ cần thiết đến buổi phỏng vấn."},{"en":"She saved the document before closing her laptop.","vi":"Cô ấy đã lưu tài liệu trước khi đóng máy tính xách tay."},{"en":"This official document describes the new safety procedures.","vi":"Văn bản chính thức này mô tả các quy trình an toàn mới."}]', '[{"phrase":"official document"},{"phrase":"legal document"},{"phrase":"sign a document"}]', NULL, '/ˈdɑːkjumənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docum/document__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 20, 'dominate', 'thống trị; chiếm ưu thế; chi phối', 'verb', '[{"en":"A few large firms dominate the global smartphone market.","vi":"Một vài công ty lớn thống trị thị trường điện thoại thông minh toàn cầu."},{"en":"Climate change dominated discussions at this year''s conference.","vi":"Biến đổi khí hậu chi phối các cuộc thảo luận tại hội nghị năm nay."},{"en":"Service industries now dominate the economy of most developed countries.","vi":"Ngành dịch vụ hiện chiếm ưu thế trong nền kinh tế của hầu hết các nước phát triển."}]', '[{"phrase":"dominate the market"},{"phrase":"dominate the economy"},{"phrase":"dominate the debate"}]', NULL, '/ˈdɑːmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domin/dominate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 21, 'emphasis', 'sự nhấn mạnh; sự chú trọng', 'noun', '[{"en":"The new curriculum places greater emphasis on practical skills.","vi":"Chương trình học mới chú trọng hơn vào các kỹ năng thực hành."},{"en":"Many teachers feel there is too much emphasis on exam results.","vi":"Nhiều giáo viên cảm thấy việc chú trọng vào kết quả thi cử là quá mức."},{"en":"The speaker repeated her final point for emphasis.","vi":"Diễn giả đã nhắc lại ý cuối cùng để nhấn mạnh."}]', '[{"phrase":"place emphasis on"},{"phrase":"strong emphasis"},{"phrase":"for emphasis"}]', 'emphasis on sth · động từ: emphasize', '/ˈemfəsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasis__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 22, 'ensure', 'đảm bảo', 'verb', '[{"en":"Please ensure that all doors are locked before leaving.","vi":"Vui lòng đảm bảo rằng tất cả các cửa đã được khóa trước khi rời đi."},{"en":"Regular testing ensures the quality of the final product.","vi":"Việc kiểm tra thường xuyên đảm bảo chất lượng của sản phẩm cuối cùng."},{"en":"The new law aims to ensure equal pay for all workers.","vi":"Luật mới nhằm đảm bảo trả lương bình đẳng cho mọi người lao động."}]', '[{"phrase":"ensure that"},{"phrase":"ensure quality"},{"phrase":"ensure safety"}]', 'ensure (đảm bảo) ≠ insure (bảo hiểm)', '/ɪnˈʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ens/ensur/ensure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 23, 'exclude', 'loại trừ; không bao gồm', 'verb', '[{"en":"Patients over 65 were excluded from the study.","vi":"Bệnh nhân trên 65 tuổi đã bị loại khỏi nghiên cứu."},{"en":"The price excludes tax and delivery charges.","vi":"Giá này chưa bao gồm thuế và phí giao hàng."},{"en":"We cannot exclude the possibility of further delays.","vi":"Chúng tôi không thể loại trừ khả năng sẽ còn chậm trễ thêm."}]', '[{"phrase":"exclude from"},{"phrase":"exclude the possibility"}]', 'exclude sb/sth from sth', '/ɪkˈskluːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exclu/exclude__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 24, 'framework', 'khuôn khổ; khung', 'noun', '[{"en":"The report provides a framework for future research.","vi":"Báo cáo đưa ra một khuôn khổ cho các nghiên cứu trong tương lai."},{"en":"Countries agreed on a legal framework to protect ocean life.","vi":"Các quốc gia đã thống nhất một khung pháp lý để bảo vệ sinh vật biển."},{"en":"Students can use this framework to organize their essays.","vi":"Sinh viên có thể dùng khung này để sắp xếp bố cục bài luận."}]', '[{"phrase":"legal framework"},{"phrase":"theoretical framework"},{"phrase":"provide a framework"},{"phrase":"framework for"}]', NULL, '/ˈfreɪmwɜːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/framework__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 25, 'fund', 'quỹ; kinh phí', 'noun', '[{"en":"The school set up a fund to help students buy books.","vi":"Nhà trường đã lập một quỹ để giúp học sinh mua sách."},{"en":"The project was canceled because of a lack of funds.","vi":"Dự án đã bị hủy do thiếu kinh phí."},{"en":"The charity is raising funds for a new children''s hospital.","vi":"Tổ chức từ thiện đang gây quỹ cho một bệnh viện nhi mới."}]', '[{"phrase":"raise funds"},{"phrase":"set up a fund"},{"phrase":"lack of funds"},{"phrase":"public funds"}]', 'cũng là động từ: fund (tài trợ)', '/fʌnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fund_/fund__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 26, 'illustrate', 'minh họa; làm rõ', 'verb', '[{"en":"The chart illustrates how prices have changed since 2010.","vi":"Biểu đồ minh họa giá cả đã thay đổi như thế nào kể từ năm 2010."},{"en":"Let me give an example to illustrate this point.","vi":"Để tôi đưa ra một ví dụ để làm rõ điểm này."},{"en":"The book is illustrated with photos taken by local students.","vi":"Cuốn sách được minh họa bằng những bức ảnh do học sinh địa phương chụp."}]', '[{"phrase":"illustrate the point"},{"phrase":"clearly illustrate"},{"phrase":"illustrate how"}]', NULL, '/ˈɪləstreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 27, 'immigrate', 'nhập cư', 'verb', '[{"en":"Her grandparents immigrated to Canada in the 1960s.","vi":"Ông bà của cô ấy đã nhập cư vào Canada trong những năm 1960."},{"en":"Many skilled workers immigrate to find better job opportunities.","vi":"Nhiều lao động có tay nghề nhập cư để tìm kiếm cơ hội việc làm tốt hơn."},{"en":"Families who immigrate often face challenges with language and housing.","vi":"Những gia đình nhập cư thường gặp khó khăn về ngôn ngữ và nhà ở."}]', '[{"phrase":"immigrate to"},{"phrase":"immigrate from"}]', 'immigrate (nhập cư vào) ≠ emigrate (di cư khỏi)', '/ˈɪmɪɡreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 28, 'imply', 'ngụ ý; hàm ý', 'verb', '[{"en":"The results imply that the treatment is less effective in older patients.","vi":"Kết quả hàm ý rằng phương pháp điều trị kém hiệu quả hơn ở bệnh nhân lớn tuổi."},{"en":"Are you implying that I made a mistake?","vi":"Có phải bạn đang ngụ ý rằng tôi đã mắc lỗi không?"},{"en":"A rise in prices does not necessarily imply higher profits.","vi":"Giá tăng không nhất thiết hàm ý lợi nhuận cao hơn."}]', '[{"phrase":"imply that"},{"phrase":"strongly imply"},{"phrase":"necessarily imply"}]', 'imply (ngụ ý) ≠ infer (suy ra)', '/ɪmˈplaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imply/imply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 29, 'initial', 'ban đầu; đầu tiên', 'adjective', '[{"en":"Initial results from the trial look very promising.","vi":"Kết quả ban đầu của cuộc thử nghiệm trông rất khả quan."},{"en":"My initial reaction was surprise, but I soon agreed.","vi":"Phản ứng đầu tiên của tôi là ngạc nhiên, nhưng tôi đã sớm đồng ý."},{"en":"The initial cost is high, but the system saves money later.","vi":"Chi phí ban đầu cao, nhưng về sau hệ thống sẽ giúp tiết kiệm tiền."}]', '[{"phrase":"initial results"},{"phrase":"initial stage"},{"phrase":"initial reaction"},{"phrase":"initial cost"}]', NULL, '/ɪˈnɪʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-01', 30, 'instance', 'trường hợp; ví dụ', 'noun', '[{"en":"Many jobs now require coding skills, for instance in banking and finance.","vi":"Nhiều công việc hiện nay đòi hỏi kỹ năng lập trình, chẳng hạn trong ngành ngân hàng và tài chính."},{"en":"There have been several instances of fraud this year.","vi":"Năm nay đã có một vài trường hợp gian lận."},{"en":"In this instance, the company agreed to refund the full amount.","vi":"Trong trường hợp này, công ty đã đồng ý hoàn lại toàn bộ số tiền."}]', '[{"phrase":"for instance"},{"phrase":"in this instance"},{"phrase":"instances of"}]', NULL, '/ˈɪnstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/instance__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-3-02', 'awl-3', 'Học thuật Sublist 3 · Bộ 2', 'Academic Word List, sublist 3', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 1, 'interact', 'tương tác; giao tiếp', 'verb', '[{"en":"Children learn social skills by interacting with other children.","vi":"Trẻ em học các kỹ năng xã hội thông qua việc giao tiếp với những đứa trẻ khác."},{"en":"Scientists studied how the two drugs interact in the body.","vi":"Các nhà khoa học đã nghiên cứu cách hai loại thuốc tương tác với nhau trong cơ thể."},{"en":"Online courses give students fewer chances to interact with their teachers.","vi":"Các khóa học trực tuyến mang lại cho sinh viên ít cơ hội giao tiếp với giáo viên hơn."}]', '[{"phrase":"interact with"},{"phrase":"interact socially"},{"phrase":"interact closely"}]', 'interact with + người/vật', '/ˌɪntərˈækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 2, 'justify', 'biện minh; chứng minh là đúng', 'verb', '[{"en":"Managers must justify any increase in spending to the board.","vi":"Các nhà quản lý phải giải trình mọi khoản chi tiêu tăng thêm trước hội đồng quản trị."},{"en":"The results do not justify such a high level of investment.","vi":"Kết quả này không đủ để chứng minh mức đầu tư cao như vậy là hợp lý."},{"en":"How can the company justify closing a factory that still makes a profit?","vi":"Làm sao công ty có thể biện minh cho việc đóng cửa một nhà máy vẫn đang có lãi?"}]', '[{"phrase":"justify a decision"},{"phrase":"justify the cost"},{"phrase":"difficult to justify"}]', 'justify + V-ing / danh từ', '/ˈdʒʌstɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justify__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 3, 'layer', 'lớp; tầng', 'noun', '[{"en":"A thin layer of dust covered the old documents.","vi":"Một lớp bụi mỏng phủ lên những tài liệu cũ."},{"en":"The ozone layer protects the earth from harmful radiation.","vi":"Tầng ô-dôn bảo vệ trái đất khỏi bức xạ có hại."},{"en":"Each new layer of management made decisions slower.","vi":"Mỗi tầng quản lý mới lại khiến việc ra quyết định chậm hơn."}]', '[{"phrase":"a thin layer"},{"phrase":"the ozone layer"},{"phrase":"layer of"},{"phrase":"outer layer"}]', NULL, '/ˈleɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/layer/layer__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 4, 'link', 'liên kết; mối liên hệ; đường dẫn', 'noun', '[{"en":"Researchers found a strong link between smoking and heart disease.","vi":"Các nhà nghiên cứu đã tìm thấy mối liên hệ chặt chẽ giữa hút thuốc và bệnh tim."},{"en":"The new railway provides a direct link between the two cities.","vi":"Tuyến đường sắt mới tạo ra một tuyến kết nối trực tiếp giữa hai thành phố."},{"en":"Please click the link in the email to complete your registration.","vi":"Vui lòng nhấp vào đường dẫn trong email để hoàn tất việc đăng ký."}]', '[{"phrase":"link between"},{"phrase":"a strong link"},{"phrase":"a direct link"},{"phrase":"click the link"}]', 'link between A and B', '/lɪŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/link_/link__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 5, 'locate', 'xác định vị trí; đặt ở (vị trí)', 'verb', '[{"en":"Engineers were unable to locate the source of the problem.","vi":"Các kỹ sư không thể xác định được nguồn gốc của vấn đề."},{"en":"The company''s head office is located in the city center.","vi":"Trụ sở chính của công ty nằm ở trung tâm thành phố."},{"en":"Many firms choose to locate near universities to attract skilled workers.","vi":"Nhiều công ty chọn đặt trụ sở gần các trường đại học để thu hút lao động có tay nghề."}]', '[{"phrase":"be located in"},{"phrase":"locate the source"},{"phrase":"conveniently located"}]', 'be located in/at/near = nằm ở', '/ˈləʊkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/locate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 6, 'maximise', 'tối đa hóa; tận dụng tối đa', 'verb', '[{"en":"Most businesses aim to maximise profits while keeping costs low.","vi":"Hầu hết các doanh nghiệp đều hướng tới tối đa hóa lợi nhuận trong khi giữ chi phí thấp."},{"en":"The office was redesigned to maximise the use of natural light.","vi":"Văn phòng được thiết kế lại để tận dụng tối đa ánh sáng tự nhiên."},{"en":"Farmers are testing new methods to maximise crop yields.","vi":"Nông dân đang thử nghiệm các phương pháp mới để tối đa hóa năng suất cây trồng."}]', '[{"phrase":"maximise profits"},{"phrase":"maximise the use of"},{"phrase":"maximise efficiency"}]', 'Anh: maximise · Mỹ: maximize', NULL, NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 7, 'minor', 'nhỏ; không quan trọng; thứ yếu', 'adjective', '[{"en":"The report contains only a few minor errors.","vi":"Bản báo cáo chỉ có một vài lỗi nhỏ."},{"en":"Most patients experienced only minor side effects from the treatment.","vi":"Phần lớn bệnh nhân chỉ gặp những tác dụng phụ nhẹ từ phương pháp điều trị."},{"en":"Price played a minor role in customers'' decisions.","vi":"Giá cả chỉ đóng vai trò thứ yếu trong quyết định của khách hàng."}]', '[{"phrase":"minor changes"},{"phrase":"minor problem"},{"phrase":"a minor role"},{"phrase":"minor injuries"}]', 'minor ≠ major', '/ˈmaɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minor__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 8, 'negate', 'vô hiệu hóa; phủ nhận', 'verb', '[{"en":"Rising costs could negate the benefits of the new system.","vi":"Chi phí tăng cao có thể làm mất đi lợi ích của hệ thống mới."},{"en":"One poor decision can negate years of careful planning.","vi":"Một quyết định tồi có thể vô hiệu hóa nhiều năm lên kế hoạch cẩn thận."},{"en":"The new evidence does not negate the earlier findings.","vi":"Bằng chứng mới không phủ nhận những phát hiện trước đó."}]', '[{"phrase":"negate the effect"},{"phrase":"negate the benefits"},{"phrase":"negate the need"}]', NULL, '/nɪˈɡeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negat/negate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 9, 'outcome', 'kết quả; hệ quả', 'noun', '[{"en":"Nobody could predict the outcome of the negotiations.","vi":"Không ai có thể dự đoán kết quả của cuộc đàm phán."},{"en":"Early treatment usually leads to better outcomes for patients.","vi":"Điều trị sớm thường mang lại kết quả tốt hơn cho bệnh nhân."},{"en":"We are still waiting for the outcome of the review.","vi":"Chúng tôi vẫn đang chờ kết quả của đợt xem xét."}]', '[{"phrase":"the outcome of"},{"phrase":"a positive outcome"},{"phrase":"predict the outcome"},{"phrase":"learning outcomes"}]', NULL, '/ˈaʊtkʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outco/outcome__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 10, 'partner', 'đối tác; cộng sự', 'noun', '[{"en":"The firm is looking for a local partner to enter the Asian market.","vi":"Công ty đang tìm một đối tác địa phương để thâm nhập thị trường châu Á."},{"en":"Over the past decade, its neighbor has become the country''s largest trading partner.","vi":"Trong thập kỷ qua, nước láng giềng đã trở thành đối tác thương mại lớn nhất của quốc gia này."},{"en":"Students worked with a partner to complete the experiment.","vi":"Sinh viên làm việc theo cặp với một bạn để hoàn thành thí nghiệm."}]', '[{"phrase":"business partner"},{"phrase":"trading partner"},{"phrase":"senior partner"},{"phrase":"partner with"}]', NULL, '/ˈpɑːrtnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 11, 'philosophy', 'triết học; triết lý; quan điểm', 'noun', '[{"en":"She studied philosophy and economics at university.","vi":"Cô ấy học triết học và kinh tế học ở trường đại học."},{"en":"The company''s philosophy is to put customers first.","vi":"Triết lý của công ty là đặt khách hàng lên hàng đầu."},{"en":"His teaching philosophy focuses on learning through practice.","vi":"Quan điểm giảng dạy của thầy ấy tập trung vào việc học qua thực hành."}]', '[{"phrase":"political philosophy"},{"phrase":"moral philosophy"},{"phrase":"business philosophy"},{"phrase":"philosophy of"}]', NULL, '/fəˈlɑːsəfi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phi/philo/philosophy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 12, 'physical', 'thể chất; vật lý; vật chất', 'adjective', '[{"en":"Regular physical activity reduces the risk of many diseases.","vi":"Hoạt động thể chất thường xuyên giúp giảm nguy cơ mắc nhiều bệnh."},{"en":"The job involves a lot of physical work outdoors.","vi":"Công việc này đòi hỏi nhiều lao động chân tay ngoài trời."},{"en":"Many shoppers now prefer online stores to physical shops.","vi":"Nhiều người mua sắm hiện nay thích cửa hàng trực tuyến hơn cửa hàng thực tế."}]', '[{"phrase":"physical activity"},{"phrase":"physical health"},{"phrase":"physical exercise"},{"phrase":"physical environment"}]', 'physical (thể chất) ≠ physics (môn vật lý)', '/ˈfɪzɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phy/physi/physical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 13, 'proportion', 'tỷ lệ; phần; sự cân đối', 'noun', '[{"en":"A large proportion of students work part-time while studying.","vi":"Một tỷ lệ lớn sinh viên vừa học vừa làm thêm bán thời gian."},{"en":"The proportion of older people in the population is rising.","vi":"Tỷ lệ người cao tuổi trong dân số đang tăng lên."},{"en":"Taxes should be paid in proportion to income.","vi":"Thuế nên được đóng theo tỷ lệ tương ứng với thu nhập."}]', '[{"phrase":"a large proportion of"},{"phrase":"the proportion of"},{"phrase":"in proportion to"},{"phrase":"a high proportion"}]', 'in proportion to = tương xứng với', '/prəˈpɔːrʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proportion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 14, 'publish', 'xuất bản; công bố; đăng tải', 'verb', '[{"en":"The study was published in a leading medical journal.","vi":"Nghiên cứu này đã được đăng trên một tạp chí y khoa hàng đầu."},{"en":"The government will publish the full report next month.","vi":"Chính phủ sẽ công bố toàn bộ bản báo cáo vào tháng tới."},{"en":"She has published three books on urban planning.","vi":"Bà ấy đã xuất bản ba cuốn sách về quy hoạch đô thị."}]', '[{"phrase":"publish a report"},{"phrase":"publish research"},{"phrase":"published in a journal"},{"phrase":"recently published"}]', NULL, '/ˈpʌblɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 15, 'react', 'phản ứng', 'verb', '[{"en":"How did investors react to the news?","vi":"Các nhà đầu tư đã phản ứng thế nào trước tin tức này?"},{"en":"The market reacted quickly to the rise in interest rates.","vi":"Thị trường đã phản ứng nhanh chóng trước việc tăng lãi suất."},{"en":"This metal reacts with oxygen to form a thin coating.","vi":"Kim loại này phản ứng với oxy để tạo thành một lớp phủ mỏng."}]', '[{"phrase":"react to"},{"phrase":"react quickly"},{"phrase":"react with"},{"phrase":"react strongly"}]', 'react to (sự việc) · react with (chất hóa học)', '/riˈækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/react__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 16, 'register', 'đăng ký; ghi danh; sổ đăng ký', 'verb', '[{"en":"All participants must register before the conference begins.","vi":"Tất cả người tham dự phải đăng ký trước khi hội nghị bắt đầu."},{"en":"More than two hundred students registered for the course this year.","vi":"Năm nay có hơn hai trăm sinh viên ghi danh vào khóa học."},{"en":"The organization is officially registered as a charity.","vi":"Tổ chức này được đăng ký chính thức là một tổ chức từ thiện."}]', '[{"phrase":"register for"},{"phrase":"register a company"},{"phrase":"officially registered"}]', 'register for + khóa học/sự kiện', '/ˈredʒɪstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/register__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 17, 'rely', 'dựa vào; phụ thuộc vào; tin cậy', 'verb', '[{"en":"Many small farmers rely on rain to water their crops.","vi":"Nhiều nông dân nhỏ phụ thuộc vào nước mưa để tưới cây trồng."},{"en":"The study relied heavily on data from online surveys.","vi":"Nghiên cứu này dựa rất nhiều vào dữ liệu từ các cuộc khảo sát trực tuyến."},{"en":"You can rely on her to finish the task on time.","vi":"Bạn có thể tin tưởng rằng cô ấy sẽ hoàn thành nhiệm vụ đúng hạn."}]', '[{"phrase":"rely on"},{"phrase":"rely heavily on"},{"phrase":"rely on data"}]', 'rely on/upon + danh từ', '/rɪˈlaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/rely_/rely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 18, 'remove', 'loại bỏ; gỡ bỏ; di dời', 'verb', '[{"en":"The new law removes barriers to international trade.","vi":"Luật mới gỡ bỏ các rào cản đối với thương mại quốc tế."},{"en":"Workers removed the old equipment from the laboratory.","vi":"Công nhân đã di dời thiết bị cũ ra khỏi phòng thí nghiệm."},{"en":"Incomplete responses were removed from the final analysis.","vi":"Những câu trả lời chưa đầy đủ đã bị loại khỏi phần phân tích cuối cùng."}]', '[{"phrase":"remove from"},{"phrase":"remove barriers"},{"phrase":"completely remove"}]', 'remove A from B', '/rɪˈmuːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remov/remove__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 19, 'scheme', 'kế hoạch; chương trình; âm mưu', 'noun', '[{"en":"The government launched a scheme to help first-time home buyers.","vi":"Chính phủ đã khởi động một chương trình hỗ trợ những người lần đầu mua nhà."},{"en":"Employees can join the company pension scheme after six months.","vi":"Nhân viên có thể tham gia chương trình lương hưu của công ty sau sáu tháng."},{"en":"Police uncovered a scheme to cheat investors out of millions.","vi":"Cảnh sát đã phát hiện một âm mưu lừa đảo các nhà đầu tư hàng triệu đô la."}]', '[{"phrase":"pension scheme"},{"phrase":"launch a scheme"},{"phrase":"pilot scheme"},{"phrase":"a scheme to"}]', 'Anh: scheme thường trung tính · Mỹ: hay mang nghĩa âm mưu', '/skiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schem/scheme__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 20, 'sequence', 'trình tự; chuỗi; dãy', 'noun', '[{"en":"The steps must be carried out in the correct sequence.","vi":"Các bước phải được thực hiện theo đúng trình tự."},{"en":"Scientists have mapped the DNA sequence of the virus.","vi":"Các nhà khoa học đã giải mã trình tự ADN của loại virus này."},{"en":"The report describes a sequence of events that led to the crisis.","vi":"Bản báo cáo mô tả chuỗi sự kiện dẫn đến cuộc khủng hoảng."}]', '[{"phrase":"a sequence of events"},{"phrase":"in sequence"},{"phrase":"the correct sequence"},{"phrase":"DNA sequence"}]', NULL, '/ˈsiːkwəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seq/seque/sequence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 21, 'sex', 'giới tính', 'noun', '[{"en":"The form asks for your name, age and sex.","vi":"Mẫu đơn yêu cầu điền tên, tuổi và giới tính của bạn."},{"en":"Participants were divided into groups by age and sex.","vi":"Những người tham gia được chia thành các nhóm theo độ tuổi và giới tính."},{"en":"The law bans discrimination on the basis of sex.","vi":"Luật pháp cấm phân biệt đối xử dựa trên giới tính."}]', '[{"phrase":"age and sex"},{"phrase":"the opposite sex"},{"phrase":"on the basis of sex"}]', 'sex (giới tính sinh học) · gender (giới tính xã hội)', '/seks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sex__/sex__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 22, 'shift', 'sự thay đổi; sự chuyển dịch; ca làm việc', 'noun', '[{"en":"There has been a major shift in public attitudes towards recycling.","vi":"Đã có một sự thay đổi lớn trong thái độ của công chúng đối với việc tái chế."},{"en":"The economy is seeing a shift from manufacturing to services.","vi":"Nền kinh tế đang chứng kiến sự chuyển dịch từ sản xuất sang dịch vụ."},{"en":"Nurses at the hospital often work twelve-hour night shifts.","vi":"Các y tá ở bệnh viện thường làm ca đêm kéo dài mười hai tiếng."}]', '[{"phrase":"a shift in"},{"phrase":"a major shift"},{"phrase":"shift toward"},{"phrase":"night shift"}]', NULL, '/ʃɪft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shift/shift__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 23, 'specify', 'nêu rõ; chỉ định cụ thể', 'verb', '[{"en":"The contract specifies the date by which the work must be finished.","vi":"Hợp đồng nêu rõ ngày mà công việc phải được hoàn thành."},{"en":"Please specify your preferred start date on the application form.","vi":"Vui lòng ghi rõ ngày bắt đầu mong muốn của bạn trong đơn đăng ký."},{"en":"The rules do not specify how the money should be spent.","vi":"Các quy định không nêu rõ số tiền nên được chi tiêu như thế nào."}]', '[{"phrase":"clearly specify"},{"phrase":"specify the date"},{"phrase":"unless otherwise specified"}]', NULL, '/ˈspesɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 24, 'sufficient', 'đủ; đầy đủ', 'adjective', '[{"en":"There is not sufficient evidence to support this claim.","vi":"Không có đủ bằng chứng để ủng hộ nhận định này."},{"en":"Make sure you allow sufficient time to complete the test.","vi":"Hãy đảm bảo bạn dành đủ thời gian để hoàn thành bài kiểm tra."},{"en":"A small increase in funding will not be sufficient.","vi":"Một khoản tăng ngân sách nhỏ sẽ không đủ."}]', '[{"phrase":"sufficient evidence"},{"phrase":"sufficient time"},{"phrase":"sufficient funds"},{"phrase":"sufficient to"}]', 'sufficient ≠ insufficient (không đủ)', '/səˈfɪʃnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffi/sufficient__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 25, 'task', 'nhiệm vụ; công việc', 'noun', '[{"en":"Each member of the team was given a specific task.","vi":"Mỗi thành viên trong nhóm được giao một nhiệm vụ cụ thể."},{"en":"Finding enough volunteers proved to be a difficult task.","vi":"Việc tìm đủ tình nguyện viên hóa ra là một nhiệm vụ khó khăn."},{"en":"Computers can now perform many tasks that once required humans.","vi":"Máy tính giờ đây có thể thực hiện nhiều công việc từng cần đến con người."}]', '[{"phrase":"perform a task"},{"phrase":"a difficult task"},{"phrase":"complete a task"},{"phrase":"the task of"}]', NULL, '/tæsk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/task_/task__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 26, 'technical', 'kỹ thuật; chuyên môn', 'adjective', '[{"en":"The launch was delayed because of a technical problem.","vi":"Buổi ra mắt bị hoãn vì một sự cố kỹ thuật."},{"en":"Try to avoid technical terms when writing for the general public.","vi":"Hãy cố tránh dùng thuật ngữ chuyên môn khi viết cho công chúng."},{"en":"Our company provides technical support to customers around the clock.","vi":"Công ty chúng tôi cung cấp hỗ trợ kỹ thuật cho khách hàng suốt ngày đêm."}]', '[{"phrase":"technical support"},{"phrase":"technical problem"},{"phrase":"technical terms"},{"phrase":"technical skills"}]', NULL, '/ˈteknɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 27, 'technique', 'kỹ thuật; phương pháp; kỹ năng', 'noun', '[{"en":"The researchers used a new technique to measure brain activity.","vi":"Các nhà nghiên cứu đã dùng một kỹ thuật mới để đo hoạt động của não."},{"en":"Good teachers use a range of techniques to keep students interested.","vi":"Giáo viên giỏi sử dụng nhiều phương pháp khác nhau để giữ hứng thú cho học sinh."},{"en":"Her writing technique improved a lot during the course.","vi":"Kỹ năng viết của cô ấy đã tiến bộ nhiều trong suốt khóa học."}]', '[{"phrase":"a new technique"},{"phrase":"use a technique"},{"phrase":"techniques for"},{"phrase":"management techniques"}]', 'technique (n: kỹ thuật, cách làm) ≠ technical (adj)', '/tekˈniːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technique__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 28, 'technology', 'công nghệ', 'noun', '[{"en":"New technology has changed the way people work.","vi":"Công nghệ mới đã thay đổi cách mọi người làm việc."},{"en":"Schools are spending more on information technology every year.","vi":"Các trường học đang chi tiêu ngày càng nhiều hơn cho công nghệ thông tin mỗi năm."},{"en":"Advances in medical technology have helped people live longer.","vi":"Những tiến bộ trong công nghệ y tế đã giúp con người sống lâu hơn."}]', '[{"phrase":"new technology"},{"phrase":"information technology"},{"phrase":"advances in technology"},{"phrase":"modern technology"}]', NULL, '/tekˈnɑːlədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technology__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 29, 'valid', 'hợp lệ; có giá trị; có cơ sở', 'adjective', '[{"en":"You need a valid passport to travel abroad.","vi":"Bạn cần một hộ chiếu còn hiệu lực để đi nước ngoài."},{"en":"The ticket is valid for three months from the date of purchase.","vi":"Vé có giá trị trong ba tháng kể từ ngày mua."},{"en":"She raised a valid point about the cost of the project.","vi":"Cô ấy đã nêu ra một ý kiến có cơ sở về chi phí của dự án."}]', '[{"phrase":"a valid point"},{"phrase":"valid for"},{"phrase":"a valid passport"},{"phrase":"valid reason"}]', 'valid ≠ invalid (không hợp lệ)', '/ˈvælɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valid/valid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-3-02', 30, 'volume', 'khối lượng; thể tích; âm lượng', 'noun', '[{"en":"The volume of online sales has doubled in five years.","vi":"Khối lượng hàng bán trực tuyến đã tăng gấp đôi trong năm năm."},{"en":"Measure the volume of water in each container.","vi":"Hãy đo thể tích nước trong mỗi bình chứa."},{"en":"Could you turn down the volume during the meeting?","vi":"Bạn có thể giảm âm lượng trong lúc họp được không?"}]', '[{"phrase":"the volume of"},{"phrase":"traffic volume"},{"phrase":"sales volume"},{"phrase":"turn down the volume"}]', NULL, '/ˈvɑːljəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volum/volume__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-4-01', 'awl-4', 'Học thuật Sublist 4 · Bộ 1', 'Academic Word List, sublist 4', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 1, 'access', 'quyền truy cập; sự tiếp cận', 'noun', '[{"en":"Students have free access to the library''s online journals.","vi":"Sinh viên được truy cập miễn phí các tạp chí trực tuyến của thư viện."},{"en":"Many rural communities still lack access to clean water.","vi":"Nhiều cộng đồng nông thôn vẫn chưa được tiếp cận nước sạch."},{"en":"Access to the building is restricted after eight in the evening.","vi":"Việc ra vào tòa nhà bị hạn chế sau tám giờ tối."}]', '[{"phrase":"have access to"},{"phrase":"gain access to"},{"phrase":"limited access"}]', 'access to + danh từ', '/ˈækses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/acces/access__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 2, 'adequate', 'đủ; thỏa đáng; đạt yêu cầu', 'adjective', '[{"en":"Many schools lack adequate funding for science equipment.","vi":"Nhiều trường học thiếu kinh phí đủ để mua thiết bị khoa học."},{"en":"The hospital could not provide adequate care for all its patients.","vi":"Bệnh viện không thể chăm sóc thỏa đáng cho tất cả bệnh nhân của mình."},{"en":"The report found that safety training at the factory was not adequate.","vi":"Báo cáo cho thấy việc đào tạo an toàn tại nhà máy chưa đạt yêu cầu."}]', '[{"phrase":"adequate funding"},{"phrase":"adequate resources"},{"phrase":"adequate care"},{"phrase":"adequate protection"}]', NULL, '/ˈædɪkwət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ade/adequ/adequate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 3, 'annual', 'hằng năm; thường niên', 'adjective', '[{"en":"The company publishes its annual report every March.","vi":"Công ty công bố báo cáo thường niên vào tháng Ba hằng năm."},{"en":"Average annual rainfall in the region has dropped sharply.","vi":"Lượng mưa trung bình hằng năm ở khu vực này đã giảm mạnh."},{"en":"Hundreds of researchers attended the annual conference in Singapore.","vi":"Hàng trăm nhà nghiên cứu đã tham dự hội nghị thường niên tại Singapore."}]', '[{"phrase":"annual report"},{"phrase":"annual meeting"},{"phrase":"annual growth"},{"phrase":"annual income"}]', NULL, '/ˈænjuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annua/annual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 4, 'apparent', 'rõ ràng; hiển nhiên; có vẻ (bề ngoài)', 'adjective', '[{"en":"It soon became apparent that the project would need more time.","vi":"Chẳng bao lâu sau, rõ ràng là dự án sẽ cần thêm thời gian."},{"en":"The effects of the new policy are already apparent in rural areas.","vi":"Tác động của chính sách mới đã thấy rõ ở các vùng nông thôn."},{"en":"Despite her apparent calm, the manager was worried about the deadline.","vi":"Dù bề ngoài có vẻ bình tĩnh, người quản lý vẫn lo lắng về hạn chót."}]', '[{"phrase":"become apparent"},{"phrase":"for no apparent reason"},{"phrase":"readily apparent"}]', 'it is apparent that + mệnh đề', '/əˈpærənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 5, 'approximate', 'xấp xỉ; gần đúng', 'adjective', '[{"en":"The approximate cost of the project is two million dollars.","vi":"Chi phí ước tính của dự án là khoảng hai triệu đô la."},{"en":"Can you give me an approximate number of participants?","vi":"Bạn có thể cho tôi biết số người tham gia xấp xỉ không?"},{"en":"These figures are only approximate and may change next month.","vi":"Những số liệu này chỉ là gần đúng và có thể thay đổi vào tháng sau."}]', '[{"phrase":"approximate cost"},{"phrase":"approximate number"},{"phrase":"approximate value"}]', 'approximately (adv): khoảng, xấp xỉ', '/əˈprɑːksɪmət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approximate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 6, 'attitude', 'thái độ; quan điểm', 'noun', '[{"en":"Public attitudes toward recycling have changed a lot in recent years.","vi":"Quan điểm của công chúng về việc tái chế đã thay đổi nhiều trong những năm gần đây."},{"en":"Employers value workers with a positive attitude and good communication skills.","vi":"Nhà tuyển dụng đánh giá cao người lao động có thái độ tích cực và kỹ năng giao tiếp tốt."},{"en":"The survey measured students'' attitudes toward learning a foreign language.","vi":"Cuộc khảo sát đo lường thái độ của học sinh đối với việc học ngoại ngữ."}]', '[{"phrase":"positive attitude"},{"phrase":"attitude toward"},{"phrase":"public attitudes"},{"phrase":"change attitudes"}]', 'attitude to/toward + danh từ / V-ing', '/ˈætɪtuːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attit/attitude__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 7, 'attribute', 'quy cho; cho là do', 'verb', '[{"en":"Researchers attribute the rise in temperatures to human activity.","vi":"Các nhà nghiên cứu cho rằng nhiệt độ tăng là do hoạt động của con người."},{"en":"The company attributed its strong profits to lower production costs.","vi":"Công ty cho rằng lợi nhuận cao là nhờ chi phí sản xuất thấp hơn."},{"en":"Much of the drop in crime can be attributed to better street lighting.","vi":"Phần lớn sự sụt giảm tội phạm có thể là nhờ đèn đường được cải thiện."}]', '[{"phrase":"attribute something to"},{"phrase":"be attributed to"},{"phrase":"largely attributed to"}]', 'attribute A to B: cho rằng A là do B · (n) attribute: thuộc tính', '/əˈtrɪbjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attri/attribute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 8, 'civil', 'dân sự; dân dụng; (thuộc) công dân', 'adjective', '[{"en":"Civil servants will receive a small pay rise next year.","vi":"Công chức sẽ được tăng lương một chút vào năm tới."},{"en":"Many universities offer degrees in civil engineering.","vi":"Nhiều trường đại học đào tạo bằng cấp ngành kỹ thuật xây dựng dân dụng."},{"en":"The case was settled in a civil court rather than a criminal one.","vi":"Vụ việc được giải quyết tại tòa dân sự thay vì tòa hình sự."}]', '[{"phrase":"civil servant"},{"phrase":"civil engineering"},{"phrase":"civil society"},{"phrase":"civil law"}]', NULL, '/ˈsɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civil__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 9, 'code', 'bộ quy tắc; mã', 'noun', '[{"en":"All employees must follow the company''s code of conduct.","vi":"Tất cả nhân viên phải tuân thủ bộ quy tắc ứng xử của công ty."},{"en":"Enter the security code that was sent to your phone.","vi":"Hãy nhập mã bảo mật đã được gửi đến điện thoại của bạn."},{"en":"The engineers spent several weeks rewriting the code for the app.","vi":"Các kỹ sư đã mất vài tuần để viết lại mã cho ứng dụng."}]', '[{"phrase":"code of conduct"},{"phrase":"security code"},{"phrase":"write code"},{"phrase":"dress code"}]', NULL, '/kəʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cod/code_/code__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 10, 'commit', 'cam kết; phạm (tội, lỗi)', 'verb', '[{"en":"The government has committed to reducing carbon emissions by 2030.","vi":"Chính phủ đã cam kết giảm lượng khí thải carbon trước năm 2030."},{"en":"Both companies are committed to improving working conditions.","vi":"Cả hai công ty đều cam kết cải thiện điều kiện làm việc."},{"en":"Most crimes are committed by a small number of offenders.","vi":"Phần lớn tội phạm là do một số ít người phạm tội gây ra."}]', '[{"phrase":"commit to"},{"phrase":"be committed to"},{"phrase":"commit a crime"},{"phrase":"commit an error"}]', 'commit – committed – committed · commit to + V-ing', '/kəˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 11, 'communicate', 'giao tiếp; truyền đạt', 'verb', '[{"en":"Good managers communicate clearly and regularly with their teams.","vi":"Người quản lý giỏi giao tiếp rõ ràng và thường xuyên với nhóm của mình."},{"en":"The findings were communicated to the public through a short video.","vi":"Kết quả nghiên cứu được truyền đạt tới công chúng qua một video ngắn."},{"en":"Many patients find it hard to communicate their symptoms to doctors.","vi":"Nhiều bệnh nhân thấy khó diễn đạt các triệu chứng của mình với bác sĩ."}]', '[{"phrase":"communicate with"},{"phrase":"communicate effectively"},{"phrase":"communicate clearly"},{"phrase":"communicate information"}]', 'communicate with somebody', '/kəˈmjuːnɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 12, 'concentrate', 'tập trung', 'verb', '[{"en":"It is difficult to concentrate in a noisy office.","vi":"Thật khó tập trung trong một văn phòng ồn ào."},{"en":"The company decided to concentrate on its core products.","vi":"Công ty quyết định tập trung vào các sản phẩm cốt lõi của mình."},{"en":"Most of the country''s population is concentrated along the coast.","vi":"Phần lớn dân số của đất nước tập trung dọc theo bờ biển."}]', '[{"phrase":"concentrate on"},{"phrase":"concentrate efforts"},{"phrase":"highly concentrated"}]', 'concentrate on + danh từ / V-ing', '/ˈkɑːnsntreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 13, 'confer', 'hội ý; trao, ban (bằng cấp, quyền)', 'verb', '[{"en":"The judges conferred briefly before announcing their decision.","vi":"Các thẩm phán hội ý nhanh trước khi công bố quyết định."},{"en":"The university conferred honorary degrees on three scientists.","vi":"Trường đại học đã trao bằng danh dự cho ba nhà khoa học."},{"en":"Membership confers certain rights, such as voting at annual meetings.","vi":"Tư cách thành viên mang lại một số quyền nhất định, như biểu quyết tại các cuộc họp thường niên."}]', '[{"phrase":"confer with"},{"phrase":"confer a degree on"},{"phrase":"confer an advantage"}]', 'confer – conferred · confer with sb (hội ý) / confer sth on sb (trao)', '/kənˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 14, 'contrast', 'sự tương phản; sự đối lập', 'noun', '[{"en":"Sales in Europe fell; in contrast, sales in Asia rose by ten percent.","vi":"Doanh số ở châu Âu giảm; ngược lại, doanh số ở châu Á tăng mười phần trăm."},{"en":"There is a sharp contrast between rich and poor neighborhoods in the city.","vi":"Có sự tương phản rõ rệt giữa các khu dân cư giàu và nghèo trong thành phố."},{"en":"The study draws a contrast between urban and rural schools.","vi":"Nghiên cứu chỉ ra sự đối lập giữa trường học ở thành thị và nông thôn."}]', '[{"phrase":"in contrast"},{"phrase":"by contrast"},{"phrase":"sharp contrast"},{"phrase":"draw a contrast"}]', 'contrast between A and B', '/ˈkɑːntræst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 15, 'cycle', 'chu kỳ; vòng tuần hoàn', 'noun', '[{"en":"The economy goes through a cycle of growth and decline.","vi":"Nền kinh tế trải qua một chu kỳ tăng trưởng và suy thoái."},{"en":"The children learned about the life cycle of a butterfly.","vi":"Bọn trẻ đã học về vòng đời của loài bướm."},{"en":"The water cycle plays a key role in shaping the climate.","vi":"Vòng tuần hoàn của nước đóng vai trò then chốt trong việc hình thành khí hậu."}]', '[{"phrase":"life cycle"},{"phrase":"water cycle"},{"phrase":"business cycle"},{"phrase":"economic cycle"}]', NULL, '/ˈsaɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cyc/cycle/cycle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 16, 'debate', 'cuộc tranh luận; sự tranh cãi', 'noun', '[{"en":"There is a growing debate about the use of AI in schools.","vi":"Ngày càng có nhiều tranh luận về việc sử dụng AI trong trường học."},{"en":"After a long debate, the committee approved the new budget.","vi":"Sau một cuộc tranh luận dài, ủy ban đã thông qua ngân sách mới."},{"en":"The causes of the crisis remain a subject of debate among economists.","vi":"Nguyên nhân của cuộc khủng hoảng vẫn là chủ đề tranh cãi giữa các nhà kinh tế học."}]', '[{"phrase":"public debate"},{"phrase":"heated debate"},{"phrase":"debate about"},{"phrase":"subject of debate"}]', NULL, '/dɪˈbeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debat/debate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 17, 'despite', 'mặc dù; bất chấp', 'preposition', '[{"en":"Despite the rain, thousands of people attended the festival.","vi":"Mặc dù trời mưa, hàng nghìn người vẫn đến dự lễ hội."},{"en":"The project was a success despite its limited budget.","vi":"Dự án đã thành công mặc dù ngân sách hạn hẹp."},{"en":"Despite rising costs, the company kept its prices unchanged.","vi":"Bất chấp chi phí tăng, công ty vẫn giữ nguyên giá bán."}]', '[{"phrase":"despite the fact that"},{"phrase":"despite efforts"},{"phrase":"despite concerns"}]', 'despite + danh từ / V-ing (không nói "despite of")', '/dɪˈspaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/despi/despite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 18, 'dimension', 'khía cạnh; kích thước; chiều', 'noun', '[{"en":"The report examines the social dimension of climate change.","vi":"Báo cáo xem xét khía cạnh xã hội của biến đổi khí hậu."},{"en":"Please measure the dimensions of the room before ordering furniture.","vi":"Vui lòng đo kích thước căn phòng trước khi đặt mua đồ nội thất."},{"en":"The discovery added a new dimension to our understanding of the disease.","vi":"Phát hiện này mở ra một khía cạnh mới trong hiểu biết của chúng ta về căn bệnh."}]', '[{"phrase":"new dimension"},{"phrase":"social dimension"},{"phrase":"add a new dimension"}]', NULL, '/daɪˈmenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimen/dimension__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 19, 'domestic', 'trong nước; nội địa; (thuộc) gia đình', 'adjective', '[{"en":"Domestic demand for electric cars rose sharply last year.","vi":"Nhu cầu trong nước đối với ô tô điện đã tăng mạnh vào năm ngoái."},{"en":"The airline plans to add more domestic flights this summer.","vi":"Hãng hàng không dự định bổ sung thêm các chuyến bay nội địa vào mùa hè này."},{"en":"In many countries, women still do most of the domestic work.","vi":"Ở nhiều quốc gia, phụ nữ vẫn đảm nhận phần lớn công việc gia đình."}]', '[{"phrase":"domestic market"},{"phrase":"domestic flights"},{"phrase":"domestic demand"},{"phrase":"gross domestic product"}]', NULL, '/dəˈmestɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domes/domestic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 20, 'emerge', 'nổi lên; xuất hiện; lộ ra', 'verb', '[{"en":"New evidence has emerged that the drug may cause side effects.","vi":"Bằng chứng mới đã lộ ra rằng loại thuốc này có thể gây tác dụng phụ."},{"en":"Several key themes emerged from the interviews.","vi":"Một số chủ đề chính đã xuất hiện từ các cuộc phỏng vấn."},{"en":"Online shopping emerged as a major trend during the last decade.","vi":"Mua sắm trực tuyến đã nổi lên như một xu hướng lớn trong thập kỷ qua."}]', '[{"phrase":"emerge from"},{"phrase":"emerge as"},{"phrase":"begin to emerge"}]', NULL, '/ɪˈmɜːrdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emerge__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 21, 'error', 'lỗi; sai sót', 'noun', '[{"en":"The report contained several errors in its calculations.","vi":"Báo cáo có một vài sai sót trong các phép tính."},{"en":"A simple human error caused the whole system to shut down.","vi":"Một lỗi đơn giản do con người đã khiến toàn bộ hệ thống ngừng hoạt động."},{"en":"Please check your answers carefully to avoid spelling errors.","vi":"Hãy kiểm tra kỹ câu trả lời để tránh lỗi chính tả."}]', '[{"phrase":"human error"},{"phrase":"make an error"},{"phrase":"spelling error"},{"phrase":"margin of error"}]', NULL, '/ˈerər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/err/error/error__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 22, 'ethnic', '(thuộc) dân tộc; sắc tộc', 'adjective', '[{"en":"Vietnam is home to fifty-four officially recognized ethnic groups.","vi":"Việt Nam có năm mươi tư dân tộc được công nhận chính thức."},{"en":"The city''s restaurants reflect its rich ethnic diversity.","vi":"Các nhà hàng của thành phố phản ánh sự đa dạng sắc tộc phong phú nơi đây."},{"en":"The study included participants from a wide range of ethnic backgrounds.","vi":"Nghiên cứu có những người tham gia đến từ nhiều nguồn gốc dân tộc khác nhau."}]', '[{"phrase":"ethnic group"},{"phrase":"ethnic minority"},{"phrase":"ethnic background"},{"phrase":"ethnic diversity"}]', NULL, '/ˈeθnɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethni/ethnic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 23, 'goal', 'mục tiêu', 'noun', '[{"en":"Our main goal is to cut waste by half.","vi":"Mục tiêu chính của chúng tôi là giảm một nửa lượng rác thải."},{"en":"The team achieved all of its goals for the year.","vi":"Nhóm đã đạt được tất cả mục tiêu đề ra trong năm."},{"en":"Setting clear goals helps students stay motivated.","vi":"Đặt mục tiêu rõ ràng giúp học sinh duy trì động lực."}]', '[{"phrase":"achieve a goal"},{"phrase":"set a goal"},{"phrase":"main goal"},{"phrase":"long-term goal"}]', NULL, '/ɡəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goa/goal_/goal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 24, 'grant', 'khoản tài trợ; trợ cấp', 'noun', '[{"en":"The research team received a large grant from the government.","vi":"Nhóm nghiên cứu đã nhận được một khoản tài trợ lớn từ chính phủ."},{"en":"She applied for a grant to study marine biology abroad.","vi":"Cô ấy đã xin trợ cấp để đi du học ngành sinh học biển."},{"en":"Small businesses can use the grant to buy new equipment.","vi":"Các doanh nghiệp nhỏ có thể dùng khoản tài trợ để mua thiết bị mới."}]', '[{"phrase":"research grant"},{"phrase":"apply for a grant"},{"phrase":"receive a grant"},{"phrase":"government grant"}]', '(v) grant: cấp, cho phép', '/ɡrænt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grant/grant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 25, 'hence', 'do đó; vì vậy', 'adverb', '[{"en":"The data was incomplete, hence the need for further research.","vi":"Dữ liệu chưa đầy đủ, do đó cần phải nghiên cứu thêm."},{"en":"Fuel prices rose sharply; hence, demand for smaller cars increased.","vi":"Giá nhiên liệu tăng mạnh; vì vậy, nhu cầu về xe cỡ nhỏ tăng lên."},{"en":"The material is light and strong, and hence ideal for aircraft.","vi":"Vật liệu này nhẹ và bền, do đó rất lý tưởng cho máy bay."}]', '[{"phrase":"hence the need"},{"phrase":"hence the name"},{"phrase":"and hence"}]', 'hence + danh từ (không cần động từ): hence the need', '/hens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hen/hence/hence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 26, 'hypothesis', 'giả thuyết', 'noun', '[{"en":"The results support the hypothesis that sleep improves memory.","vi":"Kết quả ủng hộ giả thuyết rằng giấc ngủ giúp cải thiện trí nhớ."},{"en":"The scientists designed an experiment to test their hypothesis.","vi":"Các nhà khoa học đã thiết kế một thí nghiệm để kiểm chứng giả thuyết của họ."},{"en":"Earlier studies failed to confirm this hypothesis.","vi":"Các nghiên cứu trước đây đã không xác nhận được giả thuyết này."}]', '[{"phrase":"test a hypothesis"},{"phrase":"support the hypothesis"},{"phrase":"confirm a hypothesis"},{"phrase":"working hypothesis"}]', 'số nhiều: hypotheses', '/haɪˈpɑːθəsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hyp/hypot/hypothesis__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 27, 'implement', 'thực hiện; triển khai; thi hành', 'verb', '[{"en":"The school will implement the new curriculum next year.","vi":"Nhà trường sẽ triển khai chương trình giảng dạy mới vào năm tới."},{"en":"Many of the report''s recommendations have never been implemented.","vi":"Nhiều khuyến nghị trong báo cáo chưa bao giờ được thực hiện."},{"en":"Implementing these changes will require both time and money.","vi":"Việc thực hiện những thay đổi này sẽ cần cả thời gian lẫn tiền bạc."}]', '[{"phrase":"implement a policy"},{"phrase":"implement changes"},{"phrase":"fully implement"},{"phrase":"implement recommendations"}]', NULL, '/ˈɪmplɪment/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 28, 'implicate', 'cho thấy có liên quan; làm liên lụy', 'verb', '[{"en":"Several genes have been implicated in the development of the disease.","vi":"Một số gen được cho là có liên quan đến sự phát triển của căn bệnh này."},{"en":"Poor diet is often implicated in heart problems.","vi":"Chế độ ăn uống kém thường được cho là có liên quan đến các bệnh về tim."},{"en":"The investigation implicated two senior managers in the fraud.","vi":"Cuộc điều tra cho thấy hai quản lý cấp cao có dính líu đến vụ gian lận."}]', '[{"phrase":"be implicated in"},{"phrase":"implicate somebody in"},{"phrase":"strongly implicated"}]', 'implicate sb/sth in sth · thường dùng bị động: be implicated in', '/ˈɪmplɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 29, 'impose', 'áp đặt; áp (thuế, lệnh cấm)', 'verb', '[{"en":"The government plans to impose a new tax on sugary drinks.","vi":"Chính phủ dự định áp một loại thuế mới đối với đồ uống có đường."},{"en":"The city imposed strict limits on water use during the drought.","vi":"Thành phố đã áp đặt giới hạn nghiêm ngặt về sử dụng nước trong đợt hạn hán."},{"en":"Parents should not impose their own career choices on their children.","vi":"Cha mẹ không nên áp đặt lựa chọn nghề nghiệp của mình lên con cái."}]', '[{"phrase":"impose a tax"},{"phrase":"impose restrictions"},{"phrase":"impose limits"},{"phrase":"impose on"}]', 'impose sth on sb/sth', '/ɪmˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-01', 30, 'integrate', 'hội nhập; tích hợp; kết hợp', 'verb', '[{"en":"The new software integrates easily with our existing systems.","vi":"Phần mềm mới dễ dàng tích hợp với các hệ thống hiện có của chúng tôi."},{"en":"Schools are trying to integrate technology into every subject.","vi":"Các trường học đang cố gắng kết hợp công nghệ vào mọi môn học."},{"en":"Language classes help immigrants integrate into their new communities.","vi":"Các lớp học ngôn ngữ giúp người nhập cư hòa nhập vào cộng đồng mới."}]', '[{"phrase":"integrate into"},{"phrase":"integrate with"},{"phrase":"fully integrated"},{"phrase":"integrate technology"}]', 'integrate A into/with B', '/ˈɪntɪɡreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-4-02', 'awl-4', 'Học thuật Sublist 4 · Bộ 2', 'Academic Word List, sublist 4', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 1, 'internal', 'nội bộ; bên trong', 'adjective', '[{"en":"The company launched an internal investigation into the missing funds.","vi":"Công ty đã mở một cuộc điều tra nội bộ về khoản tiền bị thất thoát."},{"en":"Staff can find the new policy on the internal website.","vi":"Nhân viên có thể xem chính sách mới trên trang web nội bộ."},{"en":"The internal structure of the cell can be seen under a microscope.","vi":"Có thể quan sát cấu trúc bên trong của tế bào dưới kính hiển vi."}]', '[{"phrase":"internal investigation"},{"phrase":"internal structure"},{"phrase":"internal communication"}]', 'trái nghĩa: external (bên ngoài)', '/ɪnˈtɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/internal__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 2, 'investigate', 'điều tra; nghiên cứu', 'verb', '[{"en":"Officials are still investigating the cause of the fire.","vi":"Các quan chức vẫn đang điều tra nguyên nhân vụ cháy."},{"en":"This study investigates the effects of sleep on memory.","vi":"Nghiên cứu này tìm hiểu tác động của giấc ngủ đối với trí nhớ."},{"en":"The manager promised to investigate every complaint from customers.","vi":"Người quản lý hứa sẽ điều tra mọi khiếu nại của khách hàng."}]', '[{"phrase":"investigate the cause"},{"phrase":"investigate the effects of"},{"phrase":"fully investigate"},{"phrase":"investigate a complaint"}]', NULL, '/ɪnˈvestɪɡeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 3, 'job', 'công việc; việc làm; nhiệm vụ', 'noun', '[{"en":"She got a job at a research institute after graduating.","vi":"Cô ấy có được việc làm tại một viện nghiên cứu sau khi tốt nghiệp."},{"en":"Thousands of jobs were lost when the factory closed.","vi":"Hàng nghìn việc làm đã mất đi khi nhà máy đóng cửa."},{"en":"It is the manager''s job to make sure deadlines are met.","vi":"Nhiệm vụ của người quản lý là đảm bảo các thời hạn được đáp ứng."}]', '[{"phrase":"get a job"},{"phrase":"lose a job"},{"phrase":"full-time job"},{"phrase":"job market"}]', NULL, '/dʒɑːb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/job/job__/job__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 4, 'label', 'nhãn; nhãn mác', 'noun', '[{"en":"Always read the label before taking any medicine.","vi":"Hãy luôn đọc nhãn trước khi uống bất kỳ loại thuốc nào."},{"en":"Food labels must list all the ingredients in the product.","vi":"Nhãn thực phẩm phải liệt kê tất cả các thành phần trong sản phẩm."},{"en":"Each sample was stored in a tube with a clear label.","vi":"Mỗi mẫu được bảo quản trong một ống nghiệm có dán nhãn rõ ràng."}]', '[{"phrase":"read the label"},{"phrase":"food label"},{"phrase":"warning label"}]', 'động từ: label = dán nhãn; gán cho cái mác', '/ˈleɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/label/label__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 5, 'mechanism', 'cơ chế; bộ máy', 'noun', '[{"en":"Scientists still do not fully understand the mechanism behind the disease.","vi":"Các nhà khoa học vẫn chưa hiểu đầy đủ cơ chế gây ra căn bệnh này."},{"en":"The city needs a better mechanism for handling public complaints.","vi":"Thành phố cần một cơ chế tốt hơn để xử lý khiếu nại của người dân."},{"en":"Sweating is the body''s natural mechanism for cooling down.","vi":"Đổ mồ hôi là cơ chế tự nhiên giúp cơ thể hạ nhiệt."}]', '[{"phrase":"mechanism for"},{"phrase":"underlying mechanism"},{"phrase":"control mechanism"}]', NULL, '/ˈmekənɪzəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mec/mecha/mechanism__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 6, 'obvious', 'rõ ràng; hiển nhiên', 'adjective', '[{"en":"The most obvious solution is not always the best one.","vi":"Giải pháp rõ ràng nhất không phải lúc nào cũng là giải pháp tốt nhất."},{"en":"It was obvious that the plan would need more funding.","vi":"Rõ ràng là kế hoạch này sẽ cần thêm kinh phí."},{"en":"For obvious reasons, the results cannot be shared yet.","vi":"Vì những lý do hiển nhiên, kết quả chưa thể được công bố."}]', '[{"phrase":"obvious reason"},{"phrase":"obvious choice"},{"phrase":"it is obvious that"},{"phrase":"fairly obvious"}]', NULL, '/ˈɑːbviəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obvious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 7, 'occupy', 'chiếm; sử dụng (nơi chốn); giữ (vị trí)', 'verb', '[{"en":"Forests occupy nearly a third of the country''s land area.","vi":"Rừng chiếm gần một phần ba diện tích đất của cả nước."},{"en":"The building is currently occupied by two small companies.","vi":"Tòa nhà hiện đang được hai công ty nhỏ sử dụng."},{"en":"Women still occupy few senior positions in the industry.","vi":"Phụ nữ vẫn giữ rất ít vị trí cấp cao trong ngành này."}]', '[{"phrase":"occupy a position"},{"phrase":"occupy space"},{"phrase":"be occupied by"}]', NULL, '/ˈɑːkjupaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occup/occupy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 8, 'option', 'lựa chọn; phương án', 'noun', '[{"en":"Renting is often the only option for young workers in big cities.","vi":"Thuê nhà thường là lựa chọn duy nhất của người lao động trẻ ở các thành phố lớn."},{"en":"The committee discussed several options for reducing costs.","vi":"Ủy ban đã thảo luận một số phương án nhằm cắt giảm chi phí."},{"en":"Students have the option of taking the course online.","vi":"Sinh viên có thể lựa chọn học khóa này trực tuyến."}]', '[{"phrase":"the only option"},{"phrase":"have the option of"},{"phrase":"consider the options"},{"phrase":"option for"}]', NULL, '/ˈɑːpʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opt/optio/option__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 9, 'output', 'sản lượng; đầu ra', 'noun', '[{"en":"Industrial output rose by three percent last year.","vi":"Sản lượng công nghiệp đã tăng ba phần trăm vào năm ngoái."},{"en":"The factory managed to double its output within two years.","vi":"Nhà máy đã tăng gấp đôi sản lượng trong vòng hai năm."},{"en":"The program displays the output as a simple table.","vi":"Chương trình hiển thị dữ liệu đầu ra dưới dạng một bảng đơn giản."}]', '[{"phrase":"industrial output"},{"phrase":"increase output"},{"phrase":"total output"},{"phrase":"economic output"}]', 'thường không đếm được; trái nghĩa: input (đầu vào)', '/ˈaʊtpʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outpu/output__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 10, 'overall', 'tổng thể; chung; toàn bộ', 'adjective', '[{"en":"The overall cost of the project was lower than expected.","vi":"Tổng chi phí của dự án thấp hơn dự kiến."},{"en":"Our overall impression of the new system was positive.","vi":"Ấn tượng chung của chúng tôi về hệ thống mới là tích cực."},{"en":"Her overall performance this year has been excellent.","vi":"Kết quả làm việc tổng thể của cô ấy trong năm nay rất xuất sắc."}]', '[{"phrase":"overall cost"},{"phrase":"overall performance"},{"phrase":"overall impression"},{"phrase":"overall effect"}]', 'trạng từ: overall = nhìn chung', '/ˌəʊvərˈɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overa/overall__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 11, 'parallel', 'song song; tương đồng', 'adjective', '[{"en":"The new road runs parallel to the river for several kilometers.","vi":"Con đường mới chạy song song với dòng sông suốt vài ki-lô-mét."},{"en":"Parallel studies were carried out in three different countries.","vi":"Các nghiên cứu song song đã được tiến hành tại ba quốc gia khác nhau."},{"en":"The two countries followed parallel paths of economic development.","vi":"Hai quốc gia đã đi theo những con đường phát triển kinh tế tương đồng."}]', '[{"phrase":"parallel to"},{"phrase":"run parallel"},{"phrase":"parallel lines"}]', 'parallel to + danh từ', '/ˈpærəlel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paral/parallel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 12, 'parameter', 'tham số; giới hạn', 'noun', '[{"en":"The research must stay within the parameters set by the ethics committee.","vi":"Nghiên cứu phải nằm trong các giới hạn do hội đồng đạo đức đặt ra."},{"en":"You can change the parameters of the model to test different scenarios.","vi":"Bạn có thể thay đổi các tham số của mô hình để thử nghiệm những tình huống khác nhau."},{"en":"Temperature is an important parameter in this experiment.","vi":"Nhiệt độ là một tham số quan trọng trong thí nghiệm này."}]', '[{"phrase":"within the parameters"},{"phrase":"set parameters"},{"phrase":"key parameter"}]', 'thường dùng ở số nhiều: parameters', '/pəˈræmɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/param/parameter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 13, 'phase', 'giai đoạn', 'noun', '[{"en":"The first phase of the project will be finished in March.","vi":"Giai đoạn đầu của dự án sẽ hoàn thành vào tháng Ba."},{"en":"The new drug is now in the final phase of testing.","vi":"Loại thuốc mới hiện đang ở giai đoạn thử nghiệm cuối cùng."},{"en":"Relations between the two firms have entered a new phase.","vi":"Quan hệ giữa hai công ty đã bước sang một giai đoạn mới."}]', '[{"phrase":"first phase"},{"phrase":"final phase"},{"phrase":"enter a new phase"},{"phrase":"phase of"}]', NULL, '/feɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pha/phase/phase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 14, 'predict', 'dự đoán; dự báo', 'verb', '[{"en":"Experts predict that prices will rise again next year.","vi":"Các chuyên gia dự đoán giá cả sẽ lại tăng vào năm tới."},{"en":"It is difficult to predict how customers will react.","vi":"Thật khó để dự đoán khách hàng sẽ phản ứng thế nào."},{"en":"The model accurately predicted the amount of rainfall last month.","vi":"Mô hình đã dự báo chính xác lượng mưa trong tháng trước."}]', '[{"phrase":"accurately predict"},{"phrase":"difficult to predict"},{"phrase":"predict the future"},{"phrase":"predict that"}]', NULL, '/prɪˈdɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predi/predict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 15, 'principal', 'chính; chủ yếu', 'adjective', '[{"en":"The principal aim of this study is to measure stress levels.","vi":"Mục tiêu chính của nghiên cứu này là đo mức độ căng thẳng."},{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chủ yếu của hòn đảo."},{"en":"Rising costs were the principal reason for the delay.","vi":"Chi phí tăng là lý do chính dẫn đến sự chậm trễ."}]', '[{"phrase":"principal aim"},{"phrase":"principal source"},{"phrase":"principal reason"}]', 'principal (chính) ≠ principle (nguyên tắc); danh từ: hiệu trưởng', '/ˈprɪnsəpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 16, 'prior', 'trước; có từ trước', 'adjective', '[{"en":"No prior experience is required for this position.","vi":"Vị trí này không yêu cầu kinh nghiệm từ trước."},{"en":"Participants signed a consent form prior to the interview.","vi":"Những người tham gia đã ký giấy đồng ý trước buổi phỏng vấn."},{"en":"Please give us prior notice if you plan to cancel.","vi":"Vui lòng báo trước cho chúng tôi nếu bạn định hủy."}]', '[{"phrase":"prior experience"},{"phrase":"prior knowledge"},{"phrase":"prior notice"},{"phrase":"prior to"}]', 'prior to = before (trang trọng)', '/ˈpraɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/prior__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 17, 'professional', 'chuyên nghiệp; (thuộc) nghề nghiệp', 'adjective', '[{"en":"You should get professional advice before signing the contract.","vi":"Bạn nên nhờ chuyên gia tư vấn trước khi ký hợp đồng."},{"en":"The course supports teachers in their professional development.","vi":"Khóa học hỗ trợ giáo viên trong việc phát triển nghề nghiệp."},{"en":"The hotel staff were friendly and very professional.","vi":"Nhân viên khách sạn thân thiện và rất chuyên nghiệp."}]', '[{"phrase":"professional advice"},{"phrase":"professional development"},{"phrase":"highly professional"},{"phrase":"professional training"}]', 'danh từ: professional = người chuyên nghiệp', '/prəˈfeʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professional__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 18, 'project', 'dự án; đề án', 'noun', '[{"en":"The research project is funded by the university.","vi":"Dự án nghiên cứu này được trường đại học tài trợ."},{"en":"She is managing a large construction project in the city center.","vi":"Cô ấy đang quản lý một dự án xây dựng lớn ở trung tâm thành phố."},{"en":"Students must complete a group project by the end of term.","vi":"Sinh viên phải hoàn thành một đề án nhóm trước cuối học kỳ."}]', '[{"phrase":"research project"},{"phrase":"manage a project"},{"phrase":"group project"},{"phrase":"project manager"}]', 'động từ project /prəˈdʒekt/ = dự kiến, chiếu', '/ˈprɑːdʒekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proje/project__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 19, 'promote', 'thúc đẩy; quảng bá; thăng chức', 'verb', '[{"en":"Lower interest rates can help promote economic growth.","vi":"Lãi suất thấp hơn có thể giúp thúc đẩy tăng trưởng kinh tế."},{"en":"The company hired an agency to promote its new product.","vi":"Công ty đã thuê một đơn vị để quảng bá sản phẩm mới."},{"en":"He was promoted to senior manager after three years.","vi":"Anh ấy được thăng chức lên quản lý cấp cao sau ba năm."}]', '[{"phrase":"promote growth"},{"phrase":"promote a product"},{"phrase":"be promoted to"},{"phrase":"actively promote"}]', NULL, '/prəˈməʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 20, 'regime', 'chế độ; cơ chế quản lý', 'noun', '[{"en":"The country introduced a stricter tax regime last year.","vi":"Quốc gia này đã áp dụng một chế độ thuế chặt chẽ hơn vào năm ngoái."},{"en":"Athletes follow a strict training regime before major competitions.","vi":"Các vận động viên tuân theo chế độ luyện tập nghiêm ngặt trước các giải đấu lớn."},{"en":"The new regulatory regime will affect thousands of small banks.","vi":"Cơ chế quản lý mới sẽ ảnh hưởng đến hàng nghìn ngân hàng nhỏ."}]', '[{"phrase":"tax regime"},{"phrase":"training regime"},{"phrase":"regulatory regime"},{"phrase":"strict regime"}]', 'cũng chỉ chính quyền, thường mang nghĩa tiêu cực', '/reɪˈʒiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regim/regime__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 21, 'resolve', 'giải quyết; quyết định', 'verb', '[{"en":"The two companies resolved their dispute without going to court.","vi":"Hai công ty đã giải quyết tranh chấp mà không cần ra tòa."},{"en":"We are working hard to resolve the problem as quickly as possible.","vi":"Chúng tôi đang nỗ lực giải quyết vấn đề nhanh nhất có thể."},{"en":"The committee resolved to review the policy next year.","vi":"Ủy ban đã quyết định xem xét lại chính sách vào năm sau."}]', '[{"phrase":"resolve a dispute"},{"phrase":"resolve a problem"},{"phrase":"resolve an issue"},{"phrase":"resolve to do"}]', NULL, '/rɪˈzɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 22, 'retain', 'giữ lại; duy trì', 'verb', '[{"en":"The company offers higher pay to retain skilled workers.","vi":"Công ty trả lương cao hơn để giữ chân lao động có tay nghề."},{"en":"The old town has retained much of its original character.","vi":"Khu phố cổ vẫn giữ được phần lớn nét đặc trưng ban đầu."},{"en":"Some students retain information better when they study in short sessions.","vi":"Một số sinh viên ghi nhớ thông tin tốt hơn khi học theo từng buổi ngắn."}]', '[{"phrase":"retain staff"},{"phrase":"retain information"},{"phrase":"retain control"},{"phrase":"retain customers"}]', NULL, '/rɪˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retain__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 23, 'series', 'loạt; chuỗi; bộ (phim)', 'noun', '[{"en":"The researchers conducted a series of experiments on young mice.","vi":"Các nhà nghiên cứu đã tiến hành một loạt thí nghiệm trên chuột non."},{"en":"A series of meetings will be held to discuss the proposal.","vi":"Một chuỗi cuộc họp sẽ được tổ chức để thảo luận về đề xuất."},{"en":"The television series explores the history of modern science.","vi":"Bộ phim truyền hình này tìm hiểu lịch sử của khoa học hiện đại."}]', '[{"phrase":"a series of"},{"phrase":"series of experiments"},{"phrase":"television series"},{"phrase":"time series"}]', 'số ít và số nhiều đều là series', '/ˈsɪriːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serie/series__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 24, 'statistic', 'số liệu thống kê', 'noun', '[{"en":"Official statistics show that unemployment fell last month.","vi":"Số liệu thống kê chính thức cho thấy tỷ lệ thất nghiệp đã giảm trong tháng trước."},{"en":"One worrying statistic is that few students finish the course.","vi":"Một số liệu đáng lo ngại là rất ít sinh viên hoàn thành khóa học."},{"en":"The report includes statistics on housing costs in major cities.","vi":"Báo cáo có kèm số liệu thống kê về chi phí nhà ở tại các thành phố lớn."}]', '[{"phrase":"official statistics"},{"phrase":"statistics show"},{"phrase":"latest statistics"}]', 'statistics (không đếm được) = môn thống kê học', '/stəˈtɪstɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/statistic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 25, 'status', 'địa vị; tình trạng; vị thế', 'noun', '[{"en":"Doctors enjoy high social status in many countries.","vi":"Ở nhiều quốc gia, bác sĩ có địa vị xã hội cao."},{"en":"You can check the status of your application online.","vi":"Bạn có thể kiểm tra tình trạng hồ sơ của mình trực tuyến."},{"en":"The city''s status as a financial center attracts foreign investors.","vi":"Vị thế trung tâm tài chính của thành phố thu hút các nhà đầu tư nước ngoài."}]', '[{"phrase":"social status"},{"phrase":"legal status"},{"phrase":"status as"},{"phrase":"check the status"}]', NULL, '/ˈsteɪtəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/statu/status__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 26, 'stress', 'căng thẳng; áp lực; sự nhấn mạnh', 'noun', '[{"en":"Long working hours can lead to high levels of stress.","vi":"Làm việc nhiều giờ có thể dẫn đến mức độ căng thẳng cao."},{"en":"Many students suffer from stress during exam periods.","vi":"Nhiều sinh viên bị áp lực trong mùa thi."},{"en":"The report places great stress on the need for training.","vi":"Báo cáo đặc biệt nhấn mạnh sự cần thiết của việc đào tạo."}]', '[{"phrase":"suffer from stress"},{"phrase":"levels of stress"},{"phrase":"under stress"},{"phrase":"place stress on"}]', 'động từ: stress = nhấn mạnh; không đếm được (nghĩa căng thẳng)', '/stres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stres/stress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 27, 'subsequent', 'tiếp theo; sau đó', 'adjective', '[{"en":"Subsequent research has confirmed the findings of the original study.","vi":"Các nghiên cứu sau đó đã xác nhận kết quả của nghiên cứu ban đầu."},{"en":"The first meeting went well, but subsequent talks were less successful.","vi":"Cuộc họp đầu tiên diễn ra tốt đẹp, nhưng các cuộc đàm phán tiếp theo kém thành công hơn."},{"en":"Prices rose sharply in the months subsequent to the announcement.","vi":"Giá cả tăng mạnh trong những tháng sau thông báo."}]', '[{"phrase":"subsequent research"},{"phrase":"in subsequent years"},{"phrase":"subsequent to"}]', 'subsequent to = after (trang trọng)', '/ˈsʌbsɪkwənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 28, 'sum', 'khoản tiền; tổng', 'noun', '[{"en":"The government spent a huge sum of money on new roads.","vi":"Chính phủ đã chi một khoản tiền khổng lồ cho các con đường mới."},{"en":"The company agreed to pay a large sum to settle the case.","vi":"Công ty đồng ý trả một khoản tiền lớn để dàn xếp vụ kiện."},{"en":"The sum of the angles in a triangle is always 180 degrees.","vi":"Tổng các góc trong một tam giác luôn bằng 180 độ."}]', '[{"phrase":"sum of money"},{"phrase":"large sum"},{"phrase":"lump sum"},{"phrase":"the sum of"}]', NULL, '/sʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/sum__/sum__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 29, 'summary', 'bản tóm tắt', 'noun', '[{"en":"Please write a brief summary of the article.","vi":"Hãy viết một bản tóm tắt ngắn gọn về bài báo."},{"en":"The report begins with a summary of the main findings.","vi":"Báo cáo mở đầu bằng phần tóm tắt các kết quả chính."},{"en":"In summary, the new policy has produced mixed results.","vi":"Tóm lại, chính sách mới đã mang lại kết quả trái chiều."}]', '[{"phrase":"brief summary"},{"phrase":"summary of"},{"phrase":"in summary"},{"phrase":"executive summary"}]', NULL, '/ˈsʌməri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summary__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-4-02', 30, 'undertake', 'tiến hành; đảm nhận; cam kết', 'verb', '[{"en":"The university undertook a major study of student health.","vi":"Trường đại học đã tiến hành một nghiên cứu lớn về sức khỏe sinh viên."},{"en":"She agreed to undertake the role of project leader.","vi":"Cô ấy đồng ý đảm nhận vai trò trưởng dự án."},{"en":"The contractor undertook to finish the work by June.","vi":"Nhà thầu cam kết hoàn thành công việc trước tháng Sáu."}]', '[{"phrase":"undertake research"},{"phrase":"undertake a study"},{"phrase":"undertake a task"},{"phrase":"undertake to do"}]', 'undertake – undertook – undertaken', '/ˌʌndərˈteɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undertake__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-5-01', 'awl-5', 'Học thuật Sublist 5 · Bộ 1', 'Academic Word List, sublist 5', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 1, 'academy', 'học viện; viện hàn lâm', 'noun', '[{"en":"She trained as a pilot at a military academy for four years.","vi":"Cô ấy được đào tạo làm phi công tại một học viện quân sự trong bốn năm."},{"en":"He was accepted into the police academy after finishing college.","vi":"Anh ấy được nhận vào học viện cảnh sát sau khi học xong đại học."},{"en":"The country''s science academy has published a new report on water safety.","vi":"Viện hàn lâm khoa học của nước này vừa công bố một báo cáo mới về an toàn nguồn nước."}]', '[{"phrase":"military academy"},{"phrase":"police academy"},{"phrase":"academy of sciences"}]', NULL, '/əˈkædəmi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aca/acade/academy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 2, 'adjust', 'điều chỉnh; thích nghi', 'verb', '[{"en":"The company adjusted its prices to reflect higher fuel costs.","vi":"Công ty đã điều chỉnh giá để phản ánh chi phí nhiên liệu tăng cao."},{"en":"It took the new students several weeks to adjust to university life.","vi":"Các sinh viên mới phải mất vài tuần để thích nghi với cuộc sống đại học."},{"en":"All figures have been adjusted for inflation to allow fair comparisons.","vi":"Tất cả số liệu đã được điều chỉnh theo lạm phát để có thể so sánh công bằng."}]', '[{"phrase":"adjust to"},{"phrase":"adjust for inflation"},{"phrase":"adjust accordingly"}]', 'adjust to + danh từ / V-ing: thích nghi với', '/əˈdʒʌst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjust__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 3, 'alter', 'thay đổi; sửa đổi', 'verb', '[{"en":"The new evidence does not alter our main conclusions.","vi":"Bằng chứng mới không làm thay đổi các kết luận chính của chúng tôi."},{"en":"Rising temperatures could significantly alter the habitats of many species.","vi":"Nhiệt độ tăng có thể làm thay đổi đáng kể môi trường sống của nhiều loài."},{"en":"The plans were altered after residents raised concerns about traffic.","vi":"Kế hoạch đã được sửa đổi sau khi người dân bày tỏ lo ngại về giao thông."}]', '[{"phrase":"significantly alter"},{"phrase":"radically alter"},{"phrase":"alter the situation"}]', NULL, '/ˈɔːltər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alter__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 4, 'amend', 'sửa đổi; bổ sung', 'verb', '[{"en":"Please amend the contract before sending it to the client.","vi":"Vui lòng sửa đổi hợp đồng trước khi gửi cho khách hàng."},{"en":"Lawmakers voted to amend the law on data protection.","vi":"Các nhà lập pháp đã bỏ phiếu sửa đổi luật về bảo vệ dữ liệu."},{"en":"The company rules were amended to allow staff to work from home.","vi":"Nội quy công ty đã được sửa đổi để cho phép nhân viên làm việc tại nhà."}]', '[{"phrase":"amend the law"},{"phrase":"amend the contract"},{"phrase":"amended version"}]', NULL, '/əˈmend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ame/amend/amend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 5, 'aware', 'nhận thức được; biết', 'adjective', '[{"en":"Many patients are not aware of the risks of the treatment.","vi":"Nhiều bệnh nhân không nhận thức được những rủi ro của phương pháp điều trị."},{"en":"We only became aware of the problem after customers complained.","vi":"Chúng tôi chỉ biết đến vấn đề sau khi khách hàng phàn nàn."},{"en":"Staff should be aware that the building will close early on Friday.","vi":"Nhân viên cần biết rằng tòa nhà sẽ đóng cửa sớm vào thứ Sáu."}]', '[{"phrase":"aware of"},{"phrase":"become aware"},{"phrase":"fully aware"},{"phrase":"well aware"}]', 'aware of + danh từ / aware that + mệnh đề', '/əˈwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/aware__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 6, 'capacity', 'sức chứa; công suất; năng lực', 'noun', '[{"en":"The stadium has a capacity of about forty thousand people.","vi":"Sân vận động có sức chứa khoảng bốn mươi nghìn người."},{"en":"The factory is now running at full capacity.","vi":"Nhà máy hiện đang hoạt động hết công suất."},{"en":"Some children have a greater capacity for learning languages than others.","vi":"Một số trẻ có năng lực học ngôn ngữ lớn hơn những trẻ khác."}]', '[{"phrase":"full capacity"},{"phrase":"production capacity"},{"phrase":"seating capacity"},{"phrase":"capacity for"}]', NULL, '/kəˈpæsəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capac/capacity__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 7, 'challenge', 'thách thức; thử thách', 'noun', '[{"en":"Climate change is one of the biggest challenges facing the world today.","vi":"Biến đổi khí hậu là một trong những thách thức lớn nhất mà thế giới đang đối mặt hiện nay."},{"en":"The new manager faces the challenge of reducing costs without cutting jobs.","vi":"Người quản lý mới phải đối mặt với thách thức giảm chi phí mà không cắt giảm việc làm."},{"en":"Learning to write academic essays was a real challenge for her.","vi":"Học viết bài luận học thuật là một thử thách thực sự đối với cô ấy."}]', '[{"phrase":"face a challenge"},{"phrase":"major challenge"},{"phrase":"meet the challenge"},{"phrase":"pose a challenge"}]', NULL, '/ˈtʃælɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chall/challenge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 8, 'clause', 'điều khoản; mệnh đề', 'noun', '[{"en":"The contract includes a clause that protects the company from losses.","vi":"Hợp đồng có một điều khoản bảo vệ công ty khỏi thua lỗ."},{"en":"Both sides agreed to remove the disputed clause from the agreement.","vi":"Cả hai bên đồng ý loại bỏ điều khoản đang tranh chấp khỏi thỏa thuận."},{"en":"In this sentence, the second clause explains the reason for the delay.","vi":"Trong câu này, mệnh đề thứ hai giải thích lý do của sự chậm trễ."}]', '[{"phrase":"clause in the contract"},{"phrase":"include a clause"},{"phrase":"relative clause"}]', NULL, '/klɔːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claus/clause__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 9, 'compound', 'hợp chất; từ ghép', 'noun', '[{"en":"Researchers found several harmful compounds in the drinking water.","vi":"Các nhà nghiên cứu đã phát hiện một số hợp chất độc hại trong nước uống."},{"en":"Water is a compound of hydrogen and oxygen.","vi":"Nước là hợp chất của hydro và oxy."},{"en":"In English, many compounds are formed by joining two shorter words.","vi":"Trong tiếng Anh, nhiều từ ghép được tạo thành bằng cách ghép hai từ ngắn hơn."}]', '[{"phrase":"chemical compound"},{"phrase":"organic compound"},{"phrase":"compound of"}]', NULL, '/ˈkɑːmpaʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compound__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 10, 'conflict', 'xung đột; mâu thuẫn', 'noun', '[{"en":"Managers need clear strategies for resolving conflicts between team members.","vi":"Các nhà quản lý cần có chiến lược rõ ràng để giải quyết xung đột giữa các thành viên trong nhóm."},{"en":"There is a clear conflict between the two sets of results.","vi":"Có sự mâu thuẫn rõ ràng giữa hai bộ kết quả."},{"en":"Board members must declare any conflict of interest before the vote.","vi":"Các thành viên hội đồng quản trị phải khai báo mọi xung đột lợi ích trước khi bỏ phiếu."}]', '[{"phrase":"resolve a conflict"},{"phrase":"conflict of interest"},{"phrase":"conflict between"},{"phrase":"in conflict with"}]', NULL, '/ˈkɑːnflɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconflict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 11, 'consult', 'hỏi ý kiến; tham khảo', 'verb', '[{"en":"You should consult a doctor before starting any new exercise program.","vi":"Bạn nên hỏi ý kiến bác sĩ trước khi bắt đầu bất kỳ chương trình tập luyện mới nào."},{"en":"The city council consulted local residents before approving the new park.","vi":"Hội đồng thành phố đã hỏi ý kiến người dân địa phương trước khi phê duyệt công viên mới."},{"en":"Students are encouraged to consult a range of sources for their essays.","vi":"Sinh viên được khuyến khích tham khảo nhiều nguồn tài liệu khác nhau cho bài luận."}]', '[{"phrase":"consult a doctor"},{"phrase":"consult a lawyer"},{"phrase":"consult with"}]', 'consult + người: hỏi ý kiến · consult + tài liệu: tra cứu, tham khảo', '/kənˈsʌlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsult__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 12, 'contact', 'sự liên lạc; sự tiếp xúc; người quen', 'noun', '[{"en":"The research team stays in regular contact with local hospitals.","vi":"Nhóm nghiên cứu thường xuyên giữ liên lạc với các bệnh viện địa phương."},{"en":"The virus spreads through close contact with infected animals.","vi":"Vi-rút lây lan qua tiếp xúc gần với động vật bị nhiễm bệnh."},{"en":"She has many useful contacts in the publishing industry.","vi":"Cô ấy có nhiều người quen hữu ích trong ngành xuất bản."}]', '[{"phrase":"in contact with"},{"phrase":"close contact"},{"phrase":"make contact"},{"phrase":"business contacts"}]', NULL, '/ˈkɑːntækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 13, 'decline', 'giảm sút; từ chối', 'verb', '[{"en":"The number of students taking foreign languages has declined sharply.","vi":"Số lượng sinh viên học ngoại ngữ đã giảm mạnh."},{"en":"Sales continued to decline during the second half of the year.","vi":"Doanh số tiếp tục giảm trong nửa cuối năm."},{"en":"The company declined to comment on reports of job cuts.","vi":"Công ty từ chối bình luận về các thông tin cắt giảm việc làm."}]', '[{"phrase":"decline sharply"},{"phrase":"decline steadily"},{"phrase":"decline to comment"}]', 'decline to + V: từ chối làm gì (lịch sự, trang trọng)', '/dɪˈklaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decli/decline__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 14, 'discrete', 'riêng biệt; rời rạc', 'adjective', '[{"en":"The course is divided into six discrete units.","vi":"Khóa học được chia thành sáu học phần riêng biệt."},{"en":"The project can be broken down into several discrete tasks.","vi":"Dự án có thể được chia nhỏ thành nhiều nhiệm vụ riêng biệt."},{"en":"Unlike height, the number of children in a family is a discrete variable.","vi":"Khác với chiều cao, số con trong một gia đình là biến rời rạc."}]', '[{"phrase":"discrete units"},{"phrase":"discrete categories"},{"phrase":"discrete variable"}]', 'discrete (riêng biệt) ≠ discreet (kín đáo)', '/dɪˈskriːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discr/discrete__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 15, 'draft', 'bản nháp; bản dự thảo', 'noun', '[{"en":"I sent my supervisor the first draft of my thesis yesterday.","vi":"Hôm qua tôi đã gửi bản nháp đầu tiên của luận văn cho người hướng dẫn."},{"en":"A draft of the new policy will be shared with staff next week.","vi":"Bản dự thảo chính sách mới sẽ được gửi cho nhân viên vào tuần tới."},{"en":"The final draft included several changes suggested by the reviewers.","vi":"Bản thảo cuối cùng có một số thay đổi do những người phản biện đề xuất."}]', '[{"phrase":"first draft"},{"phrase":"final draft"},{"phrase":"rough draft"},{"phrase":"draft of"}]', NULL, '/dræft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draft/draft__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 16, 'enable', 'cho phép; giúp có thể', 'verb', '[{"en":"The new software enables researchers to process data much faster.","vi":"Phần mềm mới giúp các nhà nghiên cứu xử lý dữ liệu nhanh hơn nhiều."},{"en":"Online courses enable people to study while working full-time.","vi":"Các khóa học trực tuyến cho phép mọi người vừa học vừa làm việc toàn thời gian."},{"en":"The grant will enable the school to build a new science lab.","vi":"Khoản tài trợ sẽ giúp nhà trường có thể xây một phòng thí nghiệm khoa học mới."}]', '[{"phrase":"enable people to"},{"phrase":"enable users to"},{"phrase":"enable someone to do something"}]', 'enable + tân ngữ + to V', '/ɪˈneɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ena/enabl/enable__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 17, 'energy', 'năng lượng; sức lực', 'noun', '[{"en":"Many countries are investing heavily in renewable energy.","vi":"Nhiều quốc gia đang đầu tư mạnh vào năng lượng tái tạo."},{"en":"New buildings must meet strict standards for energy efficiency.","vi":"Các tòa nhà mới phải đáp ứng tiêu chuẩn nghiêm ngặt về hiệu quả năng lượng."},{"en":"After a long day of meetings, I had no energy left.","vi":"Sau một ngày dài họp hành, tôi không còn chút sức lực nào."}]', '[{"phrase":"renewable energy"},{"phrase":"energy efficiency"},{"phrase":"energy consumption"},{"phrase":"solar energy"}]', NULL, '/ˈenərdʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/energ/energy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 18, 'enforce', 'thực thi; buộc tuân theo', 'verb', '[{"en":"Police officers are responsible for enforcing the law.","vi":"Cảnh sát chịu trách nhiệm thực thi pháp luật."},{"en":"The school strictly enforces its rules on mobile phone use.","vi":"Nhà trường thực thi nghiêm ngặt các quy định về việc sử dụng điện thoại di động."},{"en":"The new safety regulations will be enforced from next January.","vi":"Các quy định an toàn mới sẽ được áp dụng bắt buộc từ tháng Một năm sau."}]', '[{"phrase":"enforce the law"},{"phrase":"strictly enforce"},{"phrase":"enforce rules"},{"phrase":"enforce regulations"}]', NULL, '/ɪnˈfɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enf/enfor/enforce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 19, 'entity', 'thực thể; pháp nhân', 'noun', '[{"en":"The two companies will continue to operate as separate legal entities.","vi":"Hai công ty sẽ tiếp tục hoạt động như những pháp nhân riêng biệt."},{"en":"In the database, each customer is stored as a separate entity.","vi":"Trong cơ sở dữ liệu, mỗi khách hàng được lưu dưới dạng một thực thể riêng."},{"en":"The university and its research institute are now a single entity.","vi":"Trường đại học và viện nghiên cứu của trường nay đã trở thành một thực thể duy nhất."}]', '[{"phrase":"legal entity"},{"phrase":"separate entity"},{"phrase":"single entity"},{"phrase":"business entity"}]', NULL, '/ˈentəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entit/entity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 20, 'equivalent', 'tương đương; vật tương đương', 'adjective', '[{"en":"Applicants need a bachelor''s degree or an equivalent qualification.","vi":"Ứng viên cần có bằng cử nhân hoặc bằng cấp tương đương."},{"en":"The fine is equivalent to three months'' salary.","vi":"Khoản tiền phạt tương đương với ba tháng lương."},{"en":"There is no exact equivalent of this word in Vietnamese.","vi":"Từ này không có từ tương đương chính xác trong tiếng Việt."}]', '[{"phrase":"equivalent to"},{"phrase":"roughly equivalent"},{"phrase":"exact equivalent"}]', 'equivalent to (tính từ) · equivalent of (danh từ)', '/ɪˈkwɪvələnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equiv/equivalent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 21, 'evolve', 'tiến hóa; phát triển dần', 'verb', '[{"en":"Scientists believe that birds evolved from small dinosaurs.","vi":"Các nhà khoa học tin rằng chim đã tiến hóa từ những loài khủng long nhỏ."},{"en":"The company has evolved from a small shop into a global business.","vi":"Công ty đã phát triển từ một cửa hàng nhỏ thành một doanh nghiệp toàn cầu."},{"en":"Teaching methods continue to evolve as technology changes.","vi":"Các phương pháp giảng dạy tiếp tục phát triển khi công nghệ thay đổi."}]', '[{"phrase":"evolve from"},{"phrase":"evolve into"},{"phrase":"continue to evolve"},{"phrase":"rapidly evolving"}]', NULL, '/ɪˈvɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolv/evolve__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 22, 'expand', 'mở rộng; giãn nở', 'verb', '[{"en":"The company plans to expand into Asian markets next year.","vi":"Công ty dự định mở rộng sang các thị trường châu Á vào năm tới."},{"en":"The university has expanded its online programs to reach more students.","vi":"Trường đại học đã mở rộng các chương trình trực tuyến để tiếp cận nhiều sinh viên hơn."},{"en":"Most metals expand slightly when they are heated.","vi":"Hầu hết kim loại giãn nở nhẹ khi bị nung nóng."}]', '[{"phrase":"expand into"},{"phrase":"expand rapidly"},{"phrase":"expand services"}]', NULL, '/ɪkˈspænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 23, 'expose', 'cho tiếp xúc; phơi bày', 'verb', '[{"en":"Studying abroad exposes students to new ideas and cultures.","vi":"Du học giúp sinh viên tiếp xúc với những ý tưởng và nền văn hóa mới."},{"en":"Workers who are exposed to loud noise may suffer hearing loss.","vi":"Những công nhân tiếp xúc với tiếng ồn lớn có thể bị suy giảm thính lực."},{"en":"The investigation exposed serious weaknesses in the company''s safety system.","vi":"Cuộc điều tra đã phơi bày những điểm yếu nghiêm trọng trong hệ thống an toàn của công ty."}]', '[{"phrase":"exposed to"},{"phrase":"expose the truth"},{"phrase":"expose weaknesses"}]', 'expose sb/sth to sth: để ai/cái gì tiếp xúc với', '/ɪkˈspəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/expose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 24, 'external', 'bên ngoài', 'adjective', '[{"en":"The report was reviewed by two external experts.","vi":"Báo cáo đã được hai chuyên gia bên ngoài thẩm định."},{"en":"Small businesses are often hit hardest by external factors like rising costs.","vi":"Các doanh nghiệp nhỏ thường bị ảnh hưởng nặng nề nhất bởi các yếu tố bên ngoài như chi phí tăng."},{"en":"This cream is for external use only.","vi":"Loại kem này chỉ dùng ngoài da."}]', '[{"phrase":"external factors"},{"phrase":"external examiner"},{"phrase":"external use"},{"phrase":"external pressure"}]', 'external ≠ internal (bên trong)', '/ɪkˈstɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exter/external__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 25, 'facilitate', 'tạo điều kiện thuận lợi; điều phối', 'verb', '[{"en":"Good lighting and quiet spaces can facilitate learning.","vi":"Ánh sáng tốt và không gian yên tĩnh có thể tạo điều kiện thuận lợi cho việc học."},{"en":"The new bridge will facilitate trade between the two regions.","vi":"Cây cầu mới sẽ tạo thuận lợi cho giao thương giữa hai vùng."},{"en":"An experienced teacher facilitated the group discussion.","vi":"Một giáo viên giàu kinh nghiệm đã điều phối buổi thảo luận nhóm."}]', '[{"phrase":"facilitate learning"},{"phrase":"facilitate communication"},{"phrase":"facilitate trade"},{"phrase":"facilitate a discussion"}]', NULL, '/fəˈsɪlɪteɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facil/facilitate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 26, 'fundamental', 'cơ bản; căn bản', 'adjective', '[{"en":"There is a fundamental difference between these two approaches.","vi":"Có một sự khác biệt cơ bản giữa hai cách tiếp cận này."},{"en":"Access to clean water is a fundamental human right.","vi":"Được tiếp cận nước sạch là một quyền cơ bản của con người."},{"en":"The company needs to make fundamental changes to the way it operates.","vi":"Công ty cần thực hiện những thay đổi căn bản trong cách vận hành."}]', '[{"phrase":"fundamental difference"},{"phrase":"fundamental change"},{"phrase":"fundamental right"},{"phrase":"fundamental principle"}]', NULL, '/ˌfʌndəˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funda/fundamental__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 27, 'generate', 'tạo ra; sản sinh', 'verb', '[{"en":"Tourism generates about a third of the region''s income.","vi":"Du lịch tạo ra khoảng một phần ba thu nhập của khu vực."},{"en":"Wind turbines generate electricity without producing harmful emissions.","vi":"Tua-bin gió sản sinh điện năng mà không thải ra khí độc hại."},{"en":"The proposal has generated a lot of interest among investors.","vi":"Đề xuất này đã tạo ra nhiều sự quan tâm trong giới đầu tư."}]', '[{"phrase":"generate income"},{"phrase":"generate electricity"},{"phrase":"generate interest"},{"phrase":"generate revenue"}]', NULL, '/ˈdʒenəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 28, 'generation', 'thế hệ; sự sản xuất', 'noun', '[{"en":"Young people of this generation spend much of their time online.","vi":"Người trẻ thuộc thế hệ này dành phần lớn thời gian trên mạng."},{"en":"The family business has been passed down through three generations.","vi":"Công việc kinh doanh của gia đình đã được truyền qua ba thế hệ."},{"en":"Coal is still widely used for electricity generation in many countries.","vi":"Than vẫn được sử dụng rộng rãi để sản xuất điện ở nhiều quốc gia."}]', '[{"phrase":"younger generation"},{"phrase":"future generations"},{"phrase":"next generation"},{"phrase":"electricity generation"}]', NULL, '/ˌdʒenəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 29, 'image', 'hình ảnh; hình tượng', 'noun', '[{"en":"The company is trying to improve its public image after a difficult year.","vi":"Công ty đang cố gắng cải thiện hình ảnh trước công chúng sau một năm khó khăn."},{"en":"Satellite images show that the forest has shrunk significantly.","vi":"Ảnh vệ tinh cho thấy khu rừng đã bị thu hẹp đáng kể."},{"en":"Advertising often presents an unrealistic image of family life.","vi":"Quảng cáo thường đưa ra một hình ảnh thiếu thực tế về cuộc sống gia đình."}]', '[{"phrase":"public image"},{"phrase":"satellite image"},{"phrase":"positive image"},{"phrase":"image of"}]', NULL, '/ˈɪmɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/image/image__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-01', 30, 'liberal', 'cởi mở; phóng khoáng; rộng rãi', 'adjective', '[{"en":"She has fairly liberal views on how children should be raised.","vi":"Bà ấy có quan điểm khá cởi mở về cách nuôi dạy con cái."},{"en":"The company has a liberal policy on working from home.","vi":"Công ty có chính sách cởi mở về việc làm việc tại nhà."},{"en":"Students are encouraged to make liberal use of the library''s resources.","vi":"Sinh viên được khuyến khích sử dụng rộng rãi các tài nguyên của thư viện."}]', '[{"phrase":"liberal views"},{"phrase":"liberal attitude"},{"phrase":"liberal use of"},{"phrase":"liberal arts"}]', NULL, '/ˈlɪbərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/liber/liberal__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-6-02', 'awl-6', 'Học thuật Sublist 6 · Bộ 2', 'Academic Word List, sublist 6', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 1, 'incidence', 'tỷ lệ mắc; mức độ xảy ra', 'noun', '[{"en":"The incidence of heart disease is higher among older men.","vi":"Tỷ lệ mắc bệnh tim cao hơn ở nam giới lớn tuổi."},{"en":"Researchers recorded a sharp rise in the incidence of childhood asthma.","vi":"Các nhà nghiên cứu ghi nhận tỷ lệ mắc hen suyễn ở trẻ em tăng mạnh."},{"en":"Better street lighting has reduced the incidence of crime in the area.","vi":"Đèn đường tốt hơn đã làm giảm mức độ xảy ra tội phạm trong khu vực."}]', '[{"phrase":"high incidence"},{"phrase":"incidence of disease"},{"phrase":"increase in the incidence"},{"phrase":"reduce the incidence"}]', 'incidence of + danh từ', '/ˈɪnsɪdəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incid/incidence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 2, 'incorporate', 'kết hợp; đưa vào; sáp nhập', 'verb', '[{"en":"The new design incorporates feedback from hundreds of users.","vi":"Thiết kế mới kết hợp ý kiến phản hồi từ hàng trăm người dùng."},{"en":"Teachers are encouraged to incorporate technology into their lessons.","vi":"Giáo viên được khuyến khích đưa công nghệ vào bài giảng của mình."},{"en":"Several small firms were incorporated into the larger company last year.","vi":"Năm ngoái, một số công ty nhỏ đã được sáp nhập vào công ty lớn hơn."}]', '[{"phrase":"incorporate into"},{"phrase":"incorporate ideas"},{"phrase":"incorporate changes"},{"phrase":"fully incorporate"}]', 'incorporate A into B', '/ɪnˈkɔːrpəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incor/incorporate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 3, 'index', 'chỉ số; mục lục tra cứu', 'noun', '[{"en":"The consumer price index rose by two percent last month.","vi":"Chỉ số giá tiêu dùng đã tăng hai phần trăm vào tháng trước."},{"en":"You can find the topic quickly by checking the index at the back.","vi":"Bạn có thể tìm chủ đề nhanh chóng bằng cách xem mục lục tra cứu ở cuối sách."},{"en":"Body mass index is a common measure of healthy weight.","vi":"Chỉ số khối cơ thể là một thước đo phổ biến về cân nặng khỏe mạnh."}]', '[{"phrase":"price index"},{"phrase":"stock market index"},{"phrase":"body mass index"},{"phrase":"index of"}]', 'Số nhiều: indexes hoặc indices', '/ˈɪndeks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/index/index__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 4, 'inhibit', 'ức chế; kìm hãm; cản trở', 'verb', '[{"en":"High interest rates may inhibit economic growth.","vi":"Lãi suất cao có thể kìm hãm tăng trưởng kinh tế."},{"en":"This drug inhibits the growth of cancer cells in the laboratory.","vi":"Loại thuốc này ức chế sự phát triển của tế bào ung thư trong phòng thí nghiệm."},{"en":"Fear of making mistakes can inhibit students from speaking in class.","vi":"Nỗi sợ mắc lỗi có thể cản trở học sinh phát biểu trong lớp."}]', '[{"phrase":"inhibit growth"},{"phrase":"inhibit the development"},{"phrase":"inhibit someone from doing"}]', 'inhibit sb from doing sth', '/ɪnˈhɪbɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inh/inhib/inhibit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 5, 'initiate', 'bắt đầu; khởi xướng', 'verb', '[{"en":"The government initiated a program to improve rural schools.","vi":"Chính phủ đã khởi xướng một chương trình nhằm cải thiện các trường học ở nông thôn."},{"en":"Only a manager can initiate the payment process.","vi":"Chỉ người quản lý mới có thể bắt đầu quy trình thanh toán."},{"en":"The company has initiated legal action against its former supplier.","vi":"Công ty đã bắt đầu khởi kiện nhà cung cấp cũ của mình."}]', '[{"phrase":"initiate a program"},{"phrase":"initiate legal action"},{"phrase":"initiate change"},{"phrase":"initiate a process"}]', NULL, '/ɪˈnɪʃieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initiate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 6, 'input', 'ý kiến đóng góp; dữ liệu đầu vào', 'noun', '[{"en":"We would welcome your input on the draft proposal.","vi":"Chúng tôi rất mong nhận được ý kiến đóng góp của bạn về bản dự thảo đề xuất."},{"en":"The final plan was shaped by input from local residents.","vi":"Kế hoạch cuối cùng được hình thành dựa trên ý kiến đóng góp của người dân địa phương."},{"en":"The program checks every input before saving it to the database.","vi":"Chương trình kiểm tra mọi dữ liệu đầu vào trước khi lưu vào cơ sở dữ liệu."}]', '[{"phrase":"input from"},{"phrase":"input into"},{"phrase":"provide input"},{"phrase":"valuable input"}]', 'Nghĩa ''ý kiến đóng góp'' thường không đếm được', '/ˈɪnpʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inp/input/input__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 7, 'instruct', 'chỉ thị; hướng dẫn; dạy', 'verb', '[{"en":"Staff were instructed to leave the building immediately.","vi":"Nhân viên được chỉ thị rời khỏi tòa nhà ngay lập tức."},{"en":"The nurse instructed patients on how to take the medicine.","vi":"Y tá hướng dẫn bệnh nhân cách uống thuốc."},{"en":"Volunteers instruct children in basic swimming skills every summer.","vi":"Mỗi mùa hè, các tình nguyện viên dạy trẻ em những kỹ năng bơi cơ bản."}]', '[{"phrase":"instruct someone to do"},{"phrase":"instruct someone in"},{"phrase":"clearly instruct"}]', 'instruct sb to do sth', '/ɪnˈstrʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instruct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 8, 'intelligent', 'thông minh', 'adjective', '[{"en":"She is a highly intelligent student with a talent for mathematics.","vi":"Cô ấy là một học sinh rất thông minh và có năng khiếu toán học."},{"en":"Scientists are building intelligent systems that can learn from data.","vi":"Các nhà khoa học đang xây dựng những hệ thống thông minh có thể học từ dữ liệu."},{"en":"Dolphins are considered some of the most intelligent animals on Earth.","vi":"Cá heo được xem là một trong những loài động vật thông minh nhất trên Trái Đất."}]', '[{"phrase":"highly intelligent"},{"phrase":"intelligent system"},{"phrase":"intelligent design"},{"phrase":"intelligent life"}]', NULL, '/ɪnˈtelɪdʒənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intelligent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 9, 'interval', 'khoảng thời gian; khoảng cách', 'noun', '[{"en":"Buses leave the station at regular intervals throughout the day.","vi":"Xe buýt rời bến theo những khoảng thời gian đều đặn suốt cả ngày."},{"en":"Blood samples were taken at intervals of four hours.","vi":"Mẫu máu được lấy cách nhau bốn giờ một lần."},{"en":"There was a short interval between the two experiments.","vi":"Có một khoảng thời gian ngắn giữa hai thí nghiệm."}]', '[{"phrase":"at regular intervals"},{"phrase":"at intervals of"},{"phrase":"short interval"},{"phrase":"time interval"}]', NULL, '/ˈɪntərvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interval__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 10, 'lecture', 'bài giảng; bài diễn thuyết', 'noun', '[{"en":"The professor gave a lecture on climate change and food security.","vi":"Giáo sư đã có một bài giảng về biến đổi khí hậu và an ninh lương thực."},{"en":"Students who miss a lecture can watch the recording online.","vi":"Sinh viên nào bỏ lỡ bài giảng có thể xem bản ghi trên mạng."},{"en":"Over three hundred people attended her public lecture last night.","vi":"Hơn ba trăm người đã tham dự buổi diễn thuyết công khai của bà tối qua."}]', '[{"phrase":"give a lecture"},{"phrase":"attend a lecture"},{"phrase":"lecture on"},{"phrase":"public lecture"}]', 'lecture on + chủ đề', '/ˈlektʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lec/lectu/lecture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 11, 'migrate', 'di cư; chuyển đổi (dữ liệu, hệ thống)', 'verb', '[{"en":"Many young people migrate to cities in search of work.","vi":"Nhiều người trẻ di cư lên thành phố để tìm việc làm."},{"en":"These birds migrate south thousands of kilometers every winter.","vi":"Mỗi mùa đông, những loài chim này di cư hàng nghìn ki-lô-mét về phía nam."},{"en":"The company plans to migrate all its data to a new system.","vi":"Công ty dự định chuyển đổi toàn bộ dữ liệu sang một hệ thống mới."}]', '[{"phrase":"migrate to"},{"phrase":"migrate from"},{"phrase":"migrate south"},{"phrase":"migrate data"}]', NULL, '/ˈmaɪɡreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mig/migra/migrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 12, 'minimum', 'mức tối thiểu', 'noun', '[{"en":"Applicants need a minimum of three years'' experience.","vi":"Ứng viên cần tối thiểu ba năm kinh nghiệm."},{"en":"We should keep costs to a minimum during the first year.","vi":"Chúng ta nên giữ chi phí ở mức tối thiểu trong năm đầu tiên."},{"en":"Temperatures fell to a minimum of five degrees overnight.","vi":"Nhiệt độ giảm xuống mức thấp nhất là năm độ trong đêm."}]', '[{"phrase":"a minimum of"},{"phrase":"keep to a minimum"},{"phrase":"bare minimum"},{"phrase":"minimum wage"}]', 'Cũng dùng như tính từ: minimum wage (lương tối thiểu)', '/ˈmɪnɪməm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimum__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 13, 'ministry', 'bộ (cơ quan chính phủ)', 'noun', '[{"en":"The Ministry of Education announced changes to the national exam.","vi":"Bộ Giáo dục đã công bố những thay đổi đối với kỳ thi quốc gia."},{"en":"According to the health ministry, the number of cases is falling.","vi":"Theo Bộ Y tế, số ca bệnh đang giảm."},{"en":"She worked for the finance ministry for more than ten years.","vi":"Bà đã làm việc cho Bộ Tài chính hơn mười năm."}]', '[{"phrase":"Ministry of Education"},{"phrase":"health ministry"},{"phrase":"ministry official"},{"phrase":"government ministry"}]', NULL, '/ˈmɪnɪstri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minis/ministry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 14, 'motive', 'động cơ; lý do', 'noun', '[{"en":"Police are still trying to establish a motive for the attack.","vi":"Cảnh sát vẫn đang cố xác định động cơ của vụ tấn công."},{"en":"Profit is not the only motive for starting a business.","vi":"Lợi nhuận không phải là động cơ duy nhất để khởi nghiệp."},{"en":"Some people questioned the motives behind the sudden price cut.","vi":"Một số người đặt câu hỏi về động cơ đằng sau việc giảm giá đột ngột."}]', '[{"phrase":"motive for"},{"phrase":"profit motive"},{"phrase":"motive behind"},{"phrase":"hidden motive"}]', 'motive for + danh từ / V-ing', '/ˈməʊtɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 15, 'neutral', 'trung lập; trung tính', 'adjective', '[{"en":"Journalists should try to remain neutral when reporting the news.","vi":"Nhà báo nên cố gắng giữ thái độ trung lập khi đưa tin."},{"en":"The talks were held in a neutral country.","vi":"Các cuộc đàm phán được tổ chức tại một quốc gia trung lập."},{"en":"Pure water has a neutral pH of seven.","vi":"Nước tinh khiết có độ pH trung tính là bảy."}]', '[{"phrase":"remain neutral"},{"phrase":"neutral country"},{"phrase":"politically neutral"},{"phrase":"neutral position"}]', NULL, '/ˈnuːtrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neu/neutr/neutral__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 16, 'nevertheless', 'tuy nhiên; dù vậy', 'adverb', '[{"en":"The study was small; nevertheless, its results were very useful.","vi":"Nghiên cứu có quy mô nhỏ; tuy nhiên, kết quả của nó rất hữu ích."},{"en":"The task was difficult, but they completed it on time nevertheless.","vi":"Nhiệm vụ rất khó, dù vậy họ vẫn hoàn thành đúng hạn."},{"en":"Although prices have risen sharply, demand nevertheless remains strong.","vi":"Mặc dù giá đã tăng mạnh, nhu cầu vẫn cao."}]', '[{"phrase":"but nevertheless"},{"phrase":"nevertheless remain"}]', 'Trang trọng hơn however; thường đứng sau dấu chấm phẩy', '/ˌnevərðəˈles/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/nevertheless__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 17, 'overseas', 'ở nước ngoài; (thuộc) nước ngoài', 'adjective', '[{"en":"The university has seen a rise in overseas students this year.","vi":"Năm nay trường đại học có số lượng sinh viên nước ngoài tăng lên."},{"en":"Many firms are looking for new overseas markets.","vi":"Nhiều công ty đang tìm kiếm các thị trường mới ở nước ngoài."},{"en":"After graduating, he spent two years working overseas.","vi":"Sau khi tốt nghiệp, anh ấy đã làm việc ở nước ngoài hai năm."}]', '[{"phrase":"overseas students"},{"phrase":"overseas markets"},{"phrase":"work overseas"},{"phrase":"overseas investment"}]', 'Cũng là trạng từ: live/work overseas', '/ˌəʊvərˈsiːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overs/overseas__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 18, 'precede', 'đi trước; diễn ra trước', 'verb', '[{"en":"A short discussion of the proposal preceded the final vote.","vi":"Trước cuộc bỏ phiếu cuối cùng là một cuộc thảo luận ngắn về đề xuất."},{"en":"The economic crisis was preceded by years of rapid growth.","vi":"Trước cuộc khủng hoảng kinh tế là nhiều năm tăng trưởng nhanh."},{"en":"In English, adjectives usually precede the nouns they describe.","vi":"Trong tiếng Anh, tính từ thường đứng trước danh từ mà nó bổ nghĩa."}]', '[{"phrase":"immediately precede"},{"phrase":"be preceded by"},{"phrase":"the preceding year"}]', 'precede ≠ proceed (tiếp tục)', '/prɪˈsiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prece/precede__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 19, 'presume', 'cho rằng; giả định', 'verb', '[{"en":"I presume the meeting will start at nine as usual.","vi":"Tôi cho rằng cuộc họp sẽ bắt đầu lúc chín giờ như thường lệ."},{"en":"In law, a person is presumed innocent until proven guilty.","vi":"Theo luật, một người được giả định là vô tội cho đến khi bị chứng minh có tội."},{"en":"The researchers presumed that all participants had answered honestly.","vi":"Các nhà nghiên cứu giả định rằng tất cả người tham gia đều trả lời trung thực."}]', '[{"phrase":"presume that"},{"phrase":"presumed innocent"},{"phrase":"reasonably presume"}]', NULL, '/prɪˈzuːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presu/presume__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 20, 'rational', 'hợp lý; lý trí', 'adjective', '[{"en":"There must be a rational explanation for these strange results.","vi":"Chắc chắn phải có một lời giải thích hợp lý cho những kết quả kỳ lạ này."},{"en":"Economists often assume that consumers make rational decisions.","vi":"Các nhà kinh tế học thường giả định rằng người tiêu dùng đưa ra quyết định lý trí."},{"en":"It is hard to stay rational when you are under pressure.","vi":"Thật khó giữ được lý trí khi bạn đang chịu áp lực."}]', '[{"phrase":"rational decision"},{"phrase":"rational explanation"},{"phrase":"rational choice"},{"phrase":"perfectly rational"}]', NULL, '/ˈræʃnəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/rational__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 21, 'recover', 'hồi phục; lấy lại; thu hồi', 'verb', '[{"en":"It took her several months to recover from the operation.","vi":"Cô ấy mất vài tháng để hồi phục sau ca phẫu thuật."},{"en":"The economy is slowly recovering after two difficult years.","vi":"Nền kinh tế đang dần hồi phục sau hai năm khó khăn."},{"en":"Engineers managed to recover most of the lost files.","vi":"Các kỹ sư đã khôi phục được phần lớn các tệp bị mất."}]', '[{"phrase":"recover from"},{"phrase":"fully recover"},{"phrase":"recover costs"},{"phrase":"slowly recover"}]', 'recover from + bệnh / khó khăn', '/rɪˈkʌvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recover__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 22, 'reveal', 'tiết lộ; cho thấy', 'verb', '[{"en":"The survey revealed that most workers want flexible hours.","vi":"Cuộc khảo sát cho thấy phần lớn người lao động muốn có giờ làm linh hoạt."},{"en":"The company refused to reveal the cost of the project.","vi":"Công ty từ chối tiết lộ chi phí của dự án."},{"en":"Blood tests revealed high levels of sugar in several patients.","vi":"Xét nghiệm máu cho thấy lượng đường cao ở một số bệnh nhân."}]', '[{"phrase":"reveal that"},{"phrase":"study reveals"},{"phrase":"reveal details"},{"phrase":"reveal the truth"}]', NULL, '/rɪˈviːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revea/reveal__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 23, 'scope', 'phạm vi; cơ hội (để làm gì)', 'noun', '[{"en":"This question is beyond the scope of our study.","vi":"Câu hỏi này nằm ngoài phạm vi nghiên cứu của chúng tôi."},{"en":"The team agreed to expand the scope of the project.","vi":"Nhóm đã đồng ý mở rộng phạm vi của dự án."},{"en":"There is still plenty of scope for improvement in the service.","vi":"Dịch vụ vẫn còn nhiều cơ hội để cải thiện."}]', '[{"phrase":"beyond the scope of"},{"phrase":"scope of the project"},{"phrase":"scope for improvement"},{"phrase":"broaden the scope"}]', 'scope for + danh từ (cơ hội cho)', '/skəʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/scope/scope__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 24, 'subsidy', 'tiền trợ cấp; khoản trợ giá', 'noun', '[{"en":"Farmers receive a government subsidy to grow certain crops.","vi":"Nông dân nhận được trợ cấp của chính phủ để trồng một số loại cây nhất định."},{"en":"Fuel subsidies cost the country billions of dollars each year.","vi":"Các khoản trợ giá nhiên liệu tiêu tốn của đất nước hàng tỷ đô la mỗi năm."},{"en":"Without housing subsidies, many families could not afford rent.","vi":"Nếu không có trợ cấp nhà ở, nhiều gia đình sẽ không đủ tiền thuê nhà."}]', '[{"phrase":"government subsidy"},{"phrase":"fuel subsidies"},{"phrase":"receive a subsidy"},{"phrase":"cut subsidies"}]', NULL, '/ˈsʌbsədi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subsi/subsidy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 25, 'tape', 'băng dính; băng ghi âm/ghi hình', 'noun', '[{"en":"She sealed the box with a strip of tape.","vi":"Cô ấy dán kín chiếc hộp bằng một miếng băng dính."},{"en":"All the interviews were recorded on tape for later analysis.","vi":"Tất cả các cuộc phỏng vấn đều được ghi âm lại để phân tích sau."},{"en":"Police examined security tapes from the night of the robbery.","vi":"Cảnh sát đã xem xét băng ghi hình an ninh từ đêm xảy ra vụ cướp."}]', '[{"phrase":"on tape"},{"phrase":"adhesive tape"},{"phrase":"tape recording"},{"phrase":"masking tape"}]', 'red tape = thủ tục hành chính rườm rà', '/teɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tape_/tape__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 26, 'trace', 'truy tìm; lần ra nguồn gốc', 'verb', '[{"en":"Scientists traced the outbreak to a contaminated water supply.","vi":"Các nhà khoa học đã lần ra nguồn gốc dịch bệnh là do nguồn nước bị ô nhiễm."},{"en":"The police are still trying to trace the missing documents.","vi":"Cảnh sát vẫn đang cố truy tìm những tài liệu bị mất."},{"en":"The custom can be traced back to the sixteenth century.","vi":"Phong tục này có thể được truy nguồn gốc về thế kỷ mười sáu."}]', '[{"phrase":"trace back to"},{"phrase":"trace the source"},{"phrase":"trace the history of"}]', 'Cũng là danh từ: dấu vết (without trace)', '/treɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trace/trace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 27, 'transform', 'biến đổi; làm thay đổi hoàn toàn', 'verb', '[{"en":"The internet has transformed the way people shop.","vi":"Internet đã làm thay đổi hoàn toàn cách mọi người mua sắm."},{"en":"The old factory was transformed into a modern art center.","vi":"Nhà máy cũ đã được biến thành một trung tâm nghệ thuật hiện đại."},{"en":"During photosynthesis, plants transform light energy into chemical energy.","vi":"Trong quá trình quang hợp, thực vật biến đổi quang năng thành hóa năng."}]', '[{"phrase":"transform into"},{"phrase":"completely transform"},{"phrase":"transform the way"},{"phrase":"radically transform"}]', 'transform A into B', '/trænsˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 28, 'transport', 'giao thông vận tải; sự vận chuyển', 'noun', '[{"en":"The city plans to invest more in public transport.","vi":"Thành phố dự định đầu tư nhiều hơn vào giao thông công cộng."},{"en":"Rising fuel prices have increased the cost of transport.","vi":"Giá nhiên liệu tăng đã làm tăng chi phí vận chuyển."},{"en":"Rail transport produces less pollution than road transport.","vi":"Vận tải đường sắt gây ô nhiễm ít hơn vận tải đường bộ."}]', '[{"phrase":"public transport"},{"phrase":"means of transport"},{"phrase":"transport costs"},{"phrase":"road transport"}]', 'Anh: public transport · Mỹ: public transportation; không đếm được', '/ˈtrænspɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transport__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 29, 'underlie', 'là cơ sở của; là nguyên nhân sâu xa của', 'verb', '[{"en":"Poverty underlies many of the health problems in the region.","vi":"Nghèo đói là nguyên nhân sâu xa của nhiều vấn đề sức khỏe trong khu vực."},{"en":"The same basic principles underlie all of these theories.","vi":"Cùng những nguyên tắc cơ bản là cơ sở của tất cả các lý thuyết này."},{"en":"Researchers want to understand the processes that underlie memory loss.","vi":"Các nhà nghiên cứu muốn hiểu những quá trình là nguyên nhân gây mất trí nhớ."}]', '[{"phrase":"principles underlie"},{"phrase":"factors underlie"}]', 'underlie – underlay – underlain; thường gặp: underlying (cơ bản, tiềm ẩn)', '/ˌʌndərˈlaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/underlie__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-02', 30, 'utilise', 'sử dụng; tận dụng', 'verb', '[{"en":"The hospital needs to utilise its resources more efficiently.","vi":"Bệnh viện cần sử dụng nguồn lực của mình hiệu quả hơn."},{"en":"Farmers are utilising new technology to save water.","vi":"Nông dân đang tận dụng công nghệ mới để tiết kiệm nước."},{"en":"Much of the available land is still not fully utilised.","vi":"Phần lớn diện tích đất sẵn có vẫn chưa được tận dụng hết."}]', '[{"phrase":"utilise resources"},{"phrase":"fully utilise"},{"phrase":"effectively utilise"},{"phrase":"utilise technology"}]', 'Anh: utilise · Mỹ: utilize', NULL, NULL, NULL, NULL);
